    steep: [3150, 1250],           // the forested flank in the east
    valley: [sideX(1000), 1000],   // the side valley in the west
    gully: [gullyX(1000), 1000],   // the stream from the cirque
    floor: [CX, CY - 150],         // the floor of the cirque
    river: [3200, yVal(3200)],
