    const titled = opts.title !== "false" && opts.title !== false, T = titled ? 50 : 0;
    const C = dk ? { paper: "#242936", frame: "#5a6273", line: "#a98060", index: "#e0b98e", label: "#ecc9a0", ink: "#eddaeb", stream: "#6fb3f2", halo: "#242936", ground: "#6b5a44", groundLine: "#e0b98e", grid: "#3a4050" }
      : { paper: "#fbf8f1", frame: "#a9a294", line: "#c08a5c", index: "#8a5530", label: "#7a4a28", ink: "#1d2433", stream: "#2f7fc4", halo: "#fbf8f1", ground: "#e2d1b2", groundLine: "#8a5530", grid: "#e1e4ea" };
    let s = titled ? text(0, 30, esc(tr("cndTitle")), { "font-size": 28, "font-weight": 700 }) : "";

    // (a) the relief seen from the south, (b) the map below it, the same x
    const X0 = 20, K = 0.15, TILT = 30 * Math.PI / 180, VEX = 1.6, ZB = 700, ZT = 1470, sT = Math.sin(TILT), cT = Math.cos(TILT);
    const Y0 = T + 34 + SY * K * sT + (ZT - ZB) * VEX * K * cT;     // the front edge of the block, at its base
