    const M0 = Y0 + 46, toMap = ([x, y]) => [X0 + x * K, M0 + (SY - y) * K];
    const g3 = grid(80, 60), N1 = g3.nx + 1, hz = g3.h;
    const h3 = (x, y) => {
      const fi = Math.max(0, Math.min(g3.nx - 1e-6, x / g3.dx)), fj = Math.max(0, Math.min(g3.ny - 1e-6, y / g3.dy)), i = Math.floor(fi), j = Math.floor(fj), u = fi - i, v = fj - j;
      return hz[j * N1 + i] * (1 - u) * (1 - v) + hz[j * N1 + i + 1] * u * (1 - v) + hz[(j + 1) * N1 + i + 1] * u * v + hz[(j + 1) * N1 + i] * (1 - u) * v;
    };
    // seen from the viewer? (a ray to the south, rising tan(TILT) / VEX)
