    s += `<rect x="${X0}" y="${r1(M0)}" width="${MW}" height="${MH}" fill="${C.paper}"/>`;
    s += `<clipPath id="cnd-map"><rect x="${X0}" y="${r1(M0)}" width="${MW}" height="${MH}"/></clipPath><g clip-path="url(#cnd-map)">`;
