    s += `<path d="${thick}" fill="none" stroke="${C.index}" stroke-width="1.4" stroke-linejoin="round"/>`;
    CUTS.forEach(([l, col]) => { s += `<path d="${pathOf(lines[l])}" fill="none" stroke="${col}" stroke-width="2.4" stroke-linejoin="round"/>`; });
