    s += `</g><rect x="0.5" y="${MT + 0.5}" width="${W - 1}" height="${MH - 1}" fill="none" stroke="${th.grid}"/>`;
    // latitudes on the right edge
    for (let lat = -40; lat <= 80; lat += 20) {
      const y = P(0, lat)[1], lab = lat ? `${Math.abs(lat)}° ${lat > 0 ? "N" : "S"}` : (fr ? "équateur" : "equator");
      s += text(W - 6, y - 5, esc(lab), { "font-size": 13, fill: th.muted, "text-anchor": "end", stroke: K0.sea, "stroke-width": 3, "paint-order": "stroke", "stroke-linejoin": "round" });
    }

    // labels: name in bold, then lines; with a halo
    const label = (x, y, lines, col, anchor = "start") => lines.forEach((l, i) => {
      s += text(x, y + i * 21, esc(l), { "font-size": i ? 16 : 18, "font-weight": i ? 400 : 700, fill: i ? th.text : col, "text-anchor": anchor,
        stroke: K0.halo, "stroke-width": 3.5, "stroke-opacity": 0.9, "paint-order": "stroke", "stroke-linejoin": "round" });
    });
    const leader = (x1, y1, x2, y2, col) => { s += `<line x1="${r1(x1)}" y1="${r1(y1)}" x2="${r1(x2)}" y2="${r1(y2)}" stroke="${col}" stroke-width="1.3"/><circle cx="${r1(x2)}" cy="${r1(y2)}" r="2.6" fill="${col}"/>`; };
