    label(ax, ay, [at[0], at[1], TS.areaText(L, grl.area)], K0.grl, "end");
    leader(ax + 6, ay - 6, (gb[0] + gb[2]) / 2 - 6, (gb[1] + gb[3]) / 2 + 10, K0.grl);
    // Africa: in the Indian Ocean
    const [fx, fy] = P(58, -22);
    label(fx, fy, [tr("tsdAfrica"), TS.areaText(L, afr.area), tr("tsdTimes")(n(afr.area / grl.area))], K0.afr);
    // Russia at home: on it
    const [rx, ry] = P(100, 64);
    label(rx, ry, [tr("tsdRussia"), TS.areaText(L, rus.area), tr("tsdRusLooks")(n(fRus))], K0.rus, "middle");
    // Russia at the equator: under it
