    s += `<rect x="0" y="${KY - 13}" width="26" height="16" fill="${tint(K0.grl)}" stroke="${K0.grl}" stroke-width="1.2"/>` + text(34, KY, esc(tr("tsdHome")), { "font-size": 16 });
    const kx = 34 + tr("tsdHome").length * 8.6 + 30;
    s += `<rect x="${r1(kx)}" y="${KY - 13}" width="26" height="16" fill="${K0.grl}"/>` + text(kx + 34, KY, esc(tr("tsdMoved")), { "font-size": 16 });
    s += text(W, KY, esc(tr("tsdSource")), { "font-size": 13, fill: th.muted, "text-anchor": "end" });
