// ---- src/diagrams/cartography/vote-map.js ----
// Diagram "vote-map": the static version of the sim of the same name, for print. The CO2 law of 13 June 2021 by
// commune, twice side by side: by area (each commune with its real surface, coloured by its majority) and by people
// (a Dorling cartogram: each commune a circle whose area is proportional to its valid votes). The law was rejected by
// 51.6 %, but only 342 of 2 105 communes said yes: by area, the map is almost all "no"; the yes communes are the big
// cities, which weigh much more by people. Below: the national result and the communes as bars, and a key.
//   <div class="geores" data-diagram="vote-map"></div>
//   data-title="false": no title (on a slide, which has its own)
// Data: dist/votes.js (data/cartography/votes.json, tools/vote-data.R).
//
// R_.voteMap(votes): the geometry shared with the sim, computed once and cached: each commune's class (yes, no, tied),
// its area and centroid (km, Swiss grid LV95), the shares by area, and the Dorling cartogram (R_.voteMap(D).dorling()).
(function (G) {
  const R_ = G.GeoRes, { svgDoc, text, esc, r1 } = R_.lib;

  R_.addStrings({
    en: {
      vodTitle: "The CO₂ law, 13 June 2021: the map by area and the map by people",
      vodArea: "By area", vodAreaSub: "each commune with its real surface",
      vodPeople: "By people", vodPeopleSub: "each commune a circle, its area proportional to its valid votes",
      vodAreaBar: "area of the map", vodPeopleBar: "area of the circles",
      vodVotes: "Votes (with the Swiss abroad)", vodCommunes: n => `Communes (${n})`,
      vodYes: "yes", vodNo: "no", vodTied: "tied",
      vodKey: ["majority yes", "majority no", "tied (as many yes as no)"],
      vodScale: (a, b) => `${a} and ${b} valid votes`,
      vodCountYes: n => `${n} yes`, vodCountNo: n => `${n} no`, vodCountTied: n => `${n} tied`,
      vodSource: "Vote: Federal Statistical Office, opendata.swiss · communes as of 1.1.2026",
      vodCities: { 261: "Zurich", 6621: "Geneva", 2701: "Basel", 351: "Bern", 5586: "Lausanne", 230: "Winterthur", 1061: "Lucerne", 3203: "St. Gallen", 5192: "Lugano" },
      vodMissing: "dist/votes.js missing",
    },
    fr: {
      vodTitle: "La loi sur le CO₂, 13 juin 2021\u00a0: la carte des surfaces et la carte des personnes",
      vodArea: "Par surface", vodAreaSub: "chaque commune avec sa vraie surface",
      vodPeople: "Par personnes", vodPeopleSub: "chaque commune un cercle, sa surface proportionnelle à ses votes valables",
      vodAreaBar: "surface de la carte", vodPeopleBar: "surface des cercles",
      vodVotes: "Votes (avec les Suisses de l'étranger)", vodCommunes: n => `Communes (${n})`,
      vodYes: "oui", vodNo: "non", vodTied: "égalité",
      vodKey: ["majorité de oui", "majorité de non", "égalité (autant de oui que de non)"],
      vodScale: (a, b) => `${a} et ${b} votes valables`,
      vodCountYes: n => `${n} oui`, vodCountNo: n => `${n} non`, vodCountTied: n => `${n} à égalité`,
      vodSource: "Votation\u00a0: Office fédéral de la statistique, opendata.swiss · communes au 1.1.2026",
      vodCities: { 261: "Zurich", 6621: "Genève", 2701: "Bâle", 351: "Berne", 5586: "Lausanne", 230: "Winterthour", 1061: "Lucerne", 3203: "Saint-Gall", 5192: "Lugano" },
      vodMissing: "dist/votes.js manquant",
    },
  });

  // yes: blue-green, no: orange-red (colour-blind safe, checked in both themes); tied: grey
  const COLOURS = {
    light: { yes: "#0086a8", no: "#dd5a24", tied: "#9aa1ab", lake: "#cfe3f1", canton: "#ffffff", edge: "#ffffff", outline: "#8a93a3" },
    dark: { yes: "#22a6bd", no: "#e2662a", tied: "#7d8594", lake: "#2c4a6b", canton: "#1d2026", edge: "#1d2026", outline: "rgba(237, 218, 235, 0.45)" },
  };

  /* ---------------- Geometry ---------------- */

  // signed area (km², counterclockwise > 0 with N up) and centroid of a flat ring [E, N, E, N, …]
  function ringStats(r) {
    let a = 0, cx = 0, cy = 0;
    for (let i = 0, n = r.length; i < n; i += 2) {
      const j = (i + 2) % n, f = r[i] * r[j + 1] - r[j] * r[i + 1];
      a += f; cx += (r[i] + r[j]) * f; cy += (r[i + 1] + r[j + 1]) * f;
    }
    return a ? { a: a / 2, x: cx / (3 * a), y: cy / (3 * a) } : { a: 0, x: r[0], y: r[1] };
  }

  // The Dorling cartogram: circles of area F × (area of Switzerland) × (votes / all votes), each at the centroid of its
  // commune, then pushed apart where they overlap (the smaller one moves more) and pulled back towards their centroid,
  // a fixed number of rounds (the last ones without the pull, to clear the overlaps). Deterministic: no randomness.
  const F = 0.35, ROUNDS = 300, FREE = 180, PULL = 0.04, GAP = 0.05, CELL = 4;
  function dorling(cs, areaTotal) {
    const n = cs.length, votes = cs.reduce((s, c) => s + c.votes, 0);
    const x = new Float64Array(n), y = new Float64Array(n), r = new Float64Array(n);
    cs.forEach((c, i) => { x[i] = c.cx; y[i] = c.cy; r[i] = Math.sqrt(F * areaTotal * c.votes / votes / Math.PI); });
    const cell = v => Math.floor(v / CELL);
    for (let k = 0; k < ROUNDS; k++) {
      const grid = new Map();
      for (let i = 0; i < n; i++) {
        for (let gx = cell(x[i] - r[i]); gx <= cell(x[i] + r[i]); gx++) for (let gy = cell(y[i] - r[i]); gy <= cell(y[i] + r[i]); gy++) {
          const key = gx * 4096 + gy;
          let list = grid.get(key);
          if (!list) grid.set(key, list = []);
          list.push(i);
        }
      }
      grid.forEach((list, key) => {
        const gx = Math.floor(key / 4096 + 1e-9), gy = key - gx * 4096;
        for (let p = 0; p < list.length; p++) for (let q = p + 1; q < list.length; q++) {
          const a = list[p], b = list[q];
          // each pair once: in the cell of the corner of the overlap of their boxes
          if (cell(Math.max(x[a] - r[a], x[b] - r[b])) !== gx || cell(Math.max(y[a] - r[a], y[b] - r[b])) !== gy) continue;
          let dx = x[b] - x[a], dy = y[b] - y[a], d = Math.hypot(dx, dy);
          const over = r[a] + r[b] + GAP - d;
          if (over <= 0) continue;
          if (d < 1e-9) { const t = (a * 2.399963) % (2 * Math.PI); dx = Math.cos(t); dy = Math.sin(t); d = 1; }
          const wa = r[b] * r[b] / (r[a] * r[a] + r[b] * r[b]), s = over / d;
          x[a] -= dx * s * wa; y[a] -= dy * s * wa;
          x[b] += dx * s * (1 - wa); y[b] += dy * s * (1 - wa);
        }
      });
      if (k < ROUNDS - FREE) for (let i = 0; i < n; i++) { x[i] += PULL * (cs[i].cx - x[i]); y[i] += PULL * (cs[i].cy - y[i]); }
    }
    return cs.map((c, i) => ({ x: x[i], y: y[i], r: r[i] }));
  }

  const cache = new WeakMap();
  function voteMap(D) {
    if (cache.has(D)) return cache.get(D);
    const communes = D.communes.map(([id, name, canton, voters, yes, no, polys]) => {
      let area = 0, sx = 0, sy = 0, main = null, mainA = 0;
      polys.forEach(p => p.forEach((r, k) => {
        const s = ringStats(r), a = (k ? -1 : 1) * Math.abs(s.a);
        area += a; sx += s.x * a; sy += s.y * a;
        if (!k && Math.abs(s.a) > mainA) { mainA = Math.abs(s.a); main = r; }
      }));
      const cls = yes > no ? "yes" : yes < no ? "no" : "tied";
      return { id, name, canton, voters, yes, no, votes: yes + no, share: yes / (yes + no), cls, polys, area, cx: sx / area, cy: sy / area, main };
    });
    const sum = (f, cls) => communes.reduce((s, c) => s + (!cls || c.cls === cls ? f(c) : 0), 0);
    const areaTotal = sum(c => c.area), votesTotal = sum(c => c.votes);
    const share = f => ({ yes: sum(f, "yes") / sum(f), no: sum(f, "no") / sum(f), tied: sum(f, "tied") / sum(f) });
    const count = { yes: sum(() => 1, "yes"), no: sum(() => 1, "no"), tied: sum(() => 1, "tied") };
    let ext = [1e9, 1e9, -1e9, -1e9];
    communes.forEach(c => c.polys.forEach(p => { const r = p[0]; for (let i = 0; i < r.length; i += 2) ext = [Math.min(ext[0], r[i]), Math.min(ext[1], r[i + 1]), Math.max(ext[2], r[i]), Math.max(ext[3], r[i + 1])]; }));
    const M = {
      communes, areaTotal, votesTotal, count,
      byArea: share(c => c.area),        // shares of the map's area, by the majority of the commune
      byPeople: share(c => c.votes),     // shares of the circles' area (the valid votes), by the majority of the commune
      ext,
      // the cartogram, computed once: [{ x, y, r }] in km, in the order of the communes; ms: its runtime
      dorling() {
        if (!M.circles) {
          const t0 = (G.performance || Date).now();
          M.circles = dorling(communes, areaTotal);
          M.ms = (G.performance || Date).now() - t0;
          M.extAll = M.circles.reduce((e, c) => [Math.min(e[0], c.x - c.r), Math.min(e[1], c.y - c.r), Math.max(e[2], c.x + c.r), Math.max(e[3], c.y + c.r)], ext.slice());
        }
        return M.circles;
      },
    };
    cache.set(D, M);
    return M;
  }

  // numbers: "1 568 032" (no-break spaces), "48.4 %" / "48,4 %"
  const big = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, "\u00a0");
  const pct = (L, x, d = 0) => `${R_.num(L, 100 * x, d)}\u00a0%`;
  voteMap.COLOURS = COLOURS; voteMap.big = big; voteMap.pct = pct; voteMap.ringStats = ringStats;
  voteMap.F = F;
  // the cantons by their number (Federal Statistical Office)
  voteMap.CANTONS = ["", "ZH", "BE", "LU", "UR", "SZ", "OW", "NW", "GL", "ZG", "FR", "SO", "BS", "BL", "SH", "AR", "AI", "SG", "GR", "AG", "TG", "TI", "VD", "VS", "NE", "GE", "JU"];
  // the commune ids of the cities named on the maps
  voteMap.CITIES = [261, 6621, 2701, 351, 5586, 230, 1061, 3203, 5192];
  R_.voteMap = voteMap;

  /* ---------------- The diagram ---------------- */

  R_.diagrams["vote-map"] = function (opts = {}) {
    const th = R_.theme(opts.theme), L = opts.lang, tr = k => R_.t(L, k), dark = th.name !== "light";
    const D = R_.data && R_.data.votes;
    if (!D) return svgDoc("0 0 1000 100", text(20, 50, esc(tr("vodMissing"))), th);
    const K = COLOURS[dark ? "dark" : "light"], V = D.vote, M = voteMap(D), circles = M.dorling();
    const titled = opts.title !== "false" && opts.title !== false;
    const W = 1280, T = titled ? 56 : 0, GAPX = 40, MW = (W - GAPX) / 2;
    const [E0, N0, E1, N1] = M.extAll, k = MW / (E1 - E0), MH = Math.round((N1 - N0) * k);
    const MT = T + 62;   // top of the maps
    let s = titled ? text(0, 34, esc(tr("vodTitle")), { "font-size": 28, "font-weight": 700 }) : "";

    const ring = (r, ox) => { let d = ""; for (let i = 0; i < r.length; i += 2) d += (i ? "L" : "M") + r1(ox + (r[i] - E0) * k) + " " + r1(MT + (N1 - r[i + 1]) * k); return d + "Z"; };
    const polysPath = (polys, ox) => polys.map(p => p.map(r => ring(r, ox)).join("")).join("");

    // headings of the two maps
    [[0, "vodArea", "vodAreaSub"], [MW + GAPX, "vodPeople", "vodPeopleSub"]].forEach(([x, a, b]) => {
      s += text(x, MT - 30, esc(tr(a)), { "font-size": 22, "font-weight": 700 });
      s += text(x, MT - 9, esc(tr(b)), { "font-size": 16, fill: th.muted });
    });

    // map 1: the communes by area (one path per class), lakes, canton borders
    const lakes = D.lakes.map(p => polysPath(p, 0)).join("");
    ["no", "tied", "yes"].forEach(cls => {
      const d = M.communes.filter(c => c.cls === cls).map(c => polysPath(c.polys, 0)).join("");
      s += `<path d="${d}" fill="${K[cls]}" fill-rule="evenodd" stroke="${K.edge}" stroke-width="0.25" stroke-linejoin="round"/>`;
    });
    s += `<path d="${lakes}" fill="${K.lake}" fill-rule="evenodd"/>`;
    s += `<path d="${D.cantons.map(c => polysPath(c[4], 0)).join("")}" fill="none" stroke="${K.canton}" stroke-width="1.2" stroke-linejoin="round"/>`;

    // map 2: the cartogram, over a faint outline of the cantons
    const ox = MW + GAPX;
    s += `<path d="${D.cantons.map(c => polysPath(c[4], ox)).join("")}" fill="${dark ? "rgba(237,218,235,0.05)" : "#f1f3f6"}" stroke="${dark ? "rgba(237,218,235,0.2)" : "#d5d9e0"}" stroke-width="0.8" stroke-linejoin="round"/>`;
    const order = M.communes.map((c, i) => i).sort((a, b) => circles[b].r - circles[a].r);
    ["no", "tied", "yes"].forEach(cls => {
      const cs = order.filter(i => M.communes[i].cls === cls).map(i => {
        const c = circles[i], cx = ox + (c.x - E0) * k, cy = MT + (N1 - c.y) * k, rr = Math.max(0.35, c.r * k);
        return `<circle cx="${r1(cx)}" cy="${r1(cy)}" r="${Math.round(rr * 100) / 100}"/>`;
      }).join("");
      s += `<g fill="${K[cls]}" stroke="${K.edge}" stroke-width="0.4">${cs}</g>`;
    });

    // the cities: a name on each map
    const halo = dark ? "#1d2026" : "#ffffff";
    voteMap.CITIES.forEach(id => {
      const i = M.communes.findIndex(c => c.id === id); if (i < 0) return;
      const c = M.communes[i], o = circles[i], name = esc(tr("vodCities")[id] || c.name);
      const lab = (x, y, dy) => text(x, y + dy, name, { "font-size": 14, "font-weight": 700, "text-anchor": "middle", stroke: halo, "stroke-width": 3.5, "stroke-linejoin": "round", "paint-order": "stroke" });
      const x1 = (c.cx - E0) * k, y1 = MT + (N1 - c.cy) * k;
      s += `<circle cx="${r1(x1)}" cy="${r1(y1)}" r="2.2" fill="${th.text}" stroke="${halo}" stroke-width="1"/>` + lab(x1, y1, -6);
      const big1 = o.r * k > 9;
      s += lab(ox + (o.x - E0) * k, MT + (N1 - o.y) * k, big1 ? 5 : -o.r * k - 4);
    });

    // under each map: what the eye sees, as a bar
    const bar = (x, y, w, h, parts, label) => {
      let out = label ? text(x, y - 8, label, { "font-size": 16 }) : "", xx = x;
      parts.forEach(([v, col, lab]) => {
        const ww = v * w;
        if (ww <= 0) return;
        out += `<rect x="${r1(xx)}" y="${y}" width="${r1(Math.max(0.6, ww - (xx + ww < x + w - 0.5 ? 1.5 : 0)))}" height="${h}" fill="${col}"/>`;
        // the share inside its segment, or under it when the segment is too narrow
        if (lab && ww > lab.length * 8 + 12) out += text(xx + 8, y + h / 2 + 6, lab, { "font-size": 16, "font-weight": 700, fill: "#ffffff" });
        else if (lab) out += text(xx, y + h + 19, lab, { "font-size": 16, "font-weight": 700 });
        xx += ww;
      });
      return out;
    };
    const BY = MT + MH + 40;
    [[0, M.byArea, "vodAreaBar"], [ox, M.byPeople, "vodPeopleBar"]].forEach(([x, sh, lab]) => {
      s += bar(x, BY, MW, 26, [[sh.yes, K.yes, `${tr("vodYes")} ${pct(L, sh.yes)}`], [sh.tied, K.tied, ""], [sh.no, K.no, `${tr("vodNo")} ${pct(L, sh.no)}`]], esc(tr(lab).replace(/^./, m => m.toUpperCase())));
    });

    // the national result and the communes
    const RY = BY + 92, yesV = V.yes / (V.yes + V.no), n = M.count, all = n.yes + n.no + n.tied;
    s += bar(0, RY, MW, 26, [[yesV, K.yes, `${tr("vodYes")} ${pct(L, yesV, 1)}`], [1 - yesV, K.no, `${tr("vodNo")} ${pct(L, 1 - yesV, 1)}`]], esc(tr("vodVotes")));
    s += text(0, RY + 46, esc(`${big(V.yes)} ${tr("vodYes")} · ${big(V.no)} ${tr("vodNo")}`), { "font-size": 15, fill: th.muted });
    s += bar(ox, RY, MW, 26, [[n.yes / all, K.yes, `${big(n.yes)} (${pct(L, n.yes / all)})`], [n.tied / all, K.tied, ""], [n.no / all, K.no, `${big(n.no)} (${pct(L, n.no / all)})`]], esc(tr("vodCommunes")(big(all))));
    s += text(ox, RY + 46, esc(`${tr("vodCountYes")(big(n.yes))} · ${tr("vodCountNo")(big(n.no))} · ${tr("vodCountTied")(n.tied)}`), { "font-size": 15, fill: th.muted });

    // key and source
    const KY = RY + 82;
    let kx = 0;
    ["yes", "no", "tied"].forEach((cls, j) => {
      const t = tr("vodKey")[j];
      s += `<rect x="${kx}" y="${KY - 13}" width="18" height="16" fill="${K[cls]}"/>` + text(kx + 25, KY, esc(t), { "font-size": 16 });
      kx += 50 + t.length * 8.2;
    });
    // the size of the circles: 10 000 and 100 000 valid votes, at the right of the key
    const rOf = v => Math.sqrt(F * M.areaTotal * v / M.votesTotal / Math.PI) * k, R2 = rOf(100000), R1 = rOf(10000);
    s += `<circle cx="${r1(W - R2 - 1)}" cy="${r1(KY - 5)}" r="${r1(R2)}" fill="none" stroke="${th.text}" stroke-width="1.2"/>` +
      `<circle cx="${r1(W - 2 * R2 - 16 - R1)}" cy="${r1(KY - 5)}" r="${r1(R1)}" fill="none" stroke="${th.text}" stroke-width="1.2"/>` +
      text(W - 2 * R2 - 26 - 2 * R1, KY, esc(tr("vodScale")(big(10000), big(100000))), { "font-size": 16, "text-anchor": "end" });
    s += text(W, KY + 38, esc(tr("vodSource")), { "font-size": 13, fill: th.muted, "text-anchor": "end" });
    return svgDoc(`0 0 ${W} ${KY + 48}`, s, th, { title: tr("vodTitle") });
  };
})(globalThis);

// ---- src/diagrams/climatology/_koppen.js ----
// The Köppen-Geiger classification of a climate from its 12 monthly mean temperatures (°C) and
// precipitations (mm), as in Beck et al. (2018, 2023) after Peel et al. (2007): B (arid) is tested
// first; summer is the warmer half-year (April–September or October–March), so no latitude is needed;
// C and D are separated at 0 °C (opts.cd = -3 for Köppen's original −3 °C).
//
//   GeoRes.koppen.classify(T, P, opts) -> { code, steps, v }
//     steps: the tests in the order they are made, { key, ok, ...values } (for a step-by-step key)
//     v: the quantities used (MAT, MAP, Thot, Tcold, Pdry, Pth...)
//   GeoRes.koppen.CODES, COLORS, color(code), ink(code) (text colour on it), name(lang, code)
(function (G) {
  const R_ = G.GeoRes;

  const CODES = ["Af", "Am", "Aw", "BWh", "BWk", "BSh", "BSk", "Csa", "Csb", "Csc", "Cwa", "Cwb", "Cwc", "Cfa", "Cfb", "Cfc",
    "Dsa", "Dsb", "Dsc", "Dsd", "Dwa", "Dwb", "Dwc", "Dwd", "Dfa", "Dfb", "Dfc", "Dfd", "ET", "EF"];
  // the colours of the Köppen-Geiger maps of Beck et al. (2018)
  const COLORS = {
    Af: [0, 0, 255], Am: [0, 120, 255], Aw: [70, 170, 250], BWh: [255, 0, 0], BWk: [255, 150, 150], BSh: [245, 165, 0], BSk: [255, 220, 100],
    Csa: [255, 255, 0], Csb: [200, 200, 0], Csc: [150, 150, 0], Cwa: [150, 255, 150], Cwb: [100, 200, 100], Cwc: [50, 150, 50],
    Cfa: [200, 255, 80], Cfb: [100, 255, 80], Cfc: [50, 200, 0], Dsa: [255, 0, 255], Dsb: [200, 0, 200], Dsc: [150, 50, 150], Dsd: [150, 100, 150],
    Dwa: [170, 175, 255], Dwb: [90, 120, 220], Dwc: [75, 80, 180], Dwd: [50, 0, 135], Dfa: [0, 255, 255], Dfb: [55, 200, 255], Dfc: [0, 125, 125],
    Dfd: [0, 70, 95], ET: [178, 178, 178], EF: [102, 102, 102],
  };
  const color = code => `rgb(${(COLORS[code] || [200, 200, 200]).join(",")})`;
  // dark or white text on the colour of a code
  const ink = code => { const [r, g, b] = COLORS[code] || [200, 200, 200]; return 0.299 * r + 0.587 * g + 0.114 * b > 140 ? "#1d2433" : "#ffffff"; };

  R_.addStrings({
    en: {
      kgGroups: { A: "Tropical", B: "Arid", C: "Temperate", D: "Cold (continental)", E: "Polar" },
      kgNames: {
        Af: "Tropical rainforest", Am: "Tropical monsoon", Aw: "Tropical savanna", BWh: "Hot desert", BWk: "Cold desert",
        BSh: "Hot steppe", BSk: "Cold steppe", Csa: "Mediterranean, hot summer", Csb: "Mediterranean, warm summer", Csc: "Mediterranean, cold summer",
        Cwa: "Temperate, dry winter, hot summer", Cwb: "Temperate, dry winter, warm summer", Cwc: "Temperate, dry winter, cold summer",
        Cfa: "Temperate, no dry season, hot summer", Cfb: "Temperate, no dry season, warm summer", Cfc: "Temperate, no dry season, cold summer",
        Dsa: "Cold, dry summer, hot summer", Dsb: "Cold, dry summer, warm summer", Dsc: "Cold, dry summer, cold summer", Dsd: "Cold, dry summer, very cold winter",
        Dwa: "Cold, dry winter, hot summer", Dwb: "Cold, dry winter, warm summer", Dwc: "Cold, dry winter, cold summer", Dwd: "Cold, dry winter, very cold winter",
        Dfa: "Cold, no dry season, hot summer", Dfb: "Cold, no dry season, warm summer", Dfc: "Cold, no dry season, cold summer", Dfd: "Cold, no dry season, very cold winter",
        ET: "Tundra", EF: "Ice cap",
      },
    },
    fr: {
      kgGroups: { A: "Tropical", B: "Aride", C: "Tempéré", D: "Froid (continental)", E: "Polaire" },
      kgNames: {
        Af: "Forêt tropicale humide", Am: "Tropical de mousson", Aw: "Savane tropicale", BWh: "Désert chaud", BWk: "Désert froid",
        BSh: "Steppe chaude", BSk: "Steppe froide", Csa: "Méditerranéen, été chaud", Csb: "Méditerranéen, été tiède", Csc: "Méditerranéen, été frais",
        Cwa: "Tempéré, hiver sec, été chaud", Cwb: "Tempéré, hiver sec, été tiède", Cwc: "Tempéré, hiver sec, été frais",
        Cfa: "Tempéré, sans saison sèche, été chaud", Cfb: "Tempéré, sans saison sèche, été tiède", Cfc: "Tempéré, sans saison sèche, été frais",
        Dsa: "Froid, été sec, été chaud", Dsb: "Froid, été sec, été tiède", Dsc: "Froid, été sec, été frais", Dsd: "Froid, été sec, hiver très froid",
        Dwa: "Froid, hiver sec, été chaud", Dwb: "Froid, hiver sec, été tiède", Dwc: "Froid, hiver sec, été frais", Dwd: "Froid, hiver sec, hiver très froid",
        Dfa: "Froid, sans saison sèche, été chaud", Dfb: "Froid, sans saison sèche, été tiède", Dfc: "Froid, sans saison sèche, été frais", Dfd: "Froid, sans saison sèche, hiver très froid",
        ET: "Toundra", EF: "Calotte glaciaire",
      },
    },
  });
  const name = (lang, code) => (R_.t(lang, "kgNames") || {})[code] || code;

  const sum = a => a.reduce((s, x) => s + x, 0);
  const AMJJAS = [3, 4, 5, 6, 7, 8], ONDJFM = [9, 10, 11, 0, 1, 2];

  function classify(T, P, opts = {}) {
    const cd = opts.cd === undefined ? 0 : +opts.cd;
    const MAT = sum(T) / 12, MAP = sum(P), Thot = Math.max(...T), Tcold = Math.min(...T);
    const Tmon10 = T.filter(t => t > 10).length, Pdry = Math.min(...P);
    // summer: the warmer half-year
    const north = sum(AMJJAS.map(i => T[i])) >= sum(ONDJFM.map(i => T[i]));
    const S = (north ? AMJJAS : ONDJFM).map(i => P[i]), Wi = (north ? ONDJFM : AMJJAS).map(i => P[i]);
    const Ps = sum(S), Pw = sum(Wi), Psdry = Math.min(...S), Pswet = Math.max(...S), Pwdry = Math.min(...Wi), Pwwet = Math.max(...Wi);
    const Pth = Pw > 0.7 * MAP ? 2 * MAT : Ps > 0.7 * MAP ? 2 * MAT + 28 : 2 * MAT + 14;
    const v = { MAT, MAP, Thot, Tcold, Tmon10, Pdry, Psdry, Pswet, Pwdry, Pwwet, Ps, Pw, Pth, north, cd };
    const steps = [];
    // a test: its key, its answer, the letter it gives (yes / no), and the numbers to show
    const step = (key, ok, yes, no, extra = {}) => { steps.push(Object.assign({ key, ok, gives: ok ? yes : no }, extra)); return ok; };
    let code;
    // B: dry
    if (step("B", MAP < 10 * Pth, "B", "", { limit: 10 * Pth, seasonal: Pw > 0.7 * MAP ? "winter" : Ps > 0.7 * MAP ? "summer" : "even" })) {
      const W = step("BW", MAP < 5 * Pth, "W", "S", { limit: 5 * Pth });
      const h = step("Bh", MAT >= 18, "h", "k");
      code = "B" + (W ? "W" : "S") + (h ? "h" : "k");
    } else if (step("E", Thot <= 10, "E", "")) {
      code = step("EF", Thot <= 0, "F", "T") ? "EF" : "ET";
    } else if (step("A", Tcold >= 18, "A", "")) {
      if (step("Af", Pdry >= 60, "f", "")) code = "Af";
      else code = step("Am", Pdry >= 100 - MAP / 25, "m", "w", { limit: 100 - MAP / 25 }) ? "Am" : "Aw";
    } else {
      const C = step("C", Tcold > cd, "C", "D");
      // precipitation regime
      const s = Psdry < 40 && Psdry < Pwwet / 3, w = Pwdry < Pswet / 10;
      let second;
      if (s && w) second = Ps < Pw ? "s" : "w";
      else second = s ? "s" : w ? "w" : "f";
      step("s", second === "s", "s", "", { limit: Math.min(40, Pwwet / 3) });
      if (second !== "s") step("w", second === "w", "w", "f", { limit: Pswet / 10 });
      // summer heat
      let third;
      if (step("a", Thot >= 22, "a", "")) third = "a";
      else if (step("b", Tmon10 >= 4, "b", C ? "c" : "")) third = "b";
      else if (!C && step("d", Tcold < -38, "d", "c")) third = "d";
      else third = "c";
      code = (C ? "C" : "D") + second + third;
    }
    return { code, steps, v };
  }

  R_.koppen = { CODES, COLORS, color, ink, name, classify };
})(globalThis);

// ---- src/diagrams/climatology/_series.js ----
// Shared by the climate-change diagrams (co2-curve, ice-core, global-temperature, warming-stripes,
// glacier-massbalance, glacier-length): the time series of GeoRes.data.climate.series (dist/climate.js,
// tools/climate-series.R), the colours, a chart frame with its axes, and the colours of the stripes.
(function (G) {
  const R_ = G.GeoRes, { r1, text } = R_.lib;

  const PALETTE = {
    dark: { co2: "#5ab0ff", temp: "#ff6a5a", ice: "#9fd3ff", warm: "#ff7a5c", line: "#ffd84a", glacier: ["#9fd3ff", "#7fd1a7", "#ffd84a", "#ff9a6a", "#c58cf0", "#ffffff"] },
    light: { co2: "#1f6fd6", temp: "#d63a2b", ice: "#2f7fc4", warm: "#c8321f", line: "#c98a00", glacier: ["#1f6fd6", "#1e8a4f", "#c98a00", "#d9542b", "#8a4fc4", "#1d2433"] },
  };
  const colors = th => Object.assign({}, R_.meteo.colors(th), PALETTE[th.name === "dark" ? "dark" : "light"]);
  const series = () => (R_.data && R_.data.climate && R_.data.climate.series) || null;

  // A chart frame: box {x, y, w, h}, x and y domains [min, max]; returns scales and the SVG of the axes.
  // ticks: { x: [values], y: [values], xfmt, yfmt }, labels: { x, y }
  function frame(C, box, xd, yd, ticks = {}, labels = {}, L) {
    const X = v => box.x + (v - xd[0]) / (xd[1] - xd[0]) * box.w, Y = v => box.y + box.h - (v - yd[0]) / (yd[1] - yd[0]) * box.h;
    const fx = ticks.xfmt || (v => v), fy = ticks.yfmt || (v => R_.num(L, v, 0));
    let s = "";
    (ticks.y || []).forEach(v => {
      s += `<line x1="${r1(box.x)}" x2="${r1(box.x + box.w)}" y1="${r1(Y(v))}" y2="${r1(Y(v))}" stroke="${C.grid}"/>`;
      s += text(box.x - 10, Y(v) + 5, fy(v), { "text-anchor": "end", "font-size": 15, fill: C.muted });
    });
    (ticks.x || []).forEach(v => {
      s += `<line x1="${r1(X(v))}" x2="${r1(X(v))}" y1="${r1(box.y + box.h)}" y2="${r1(box.y + box.h + 6)}" stroke="${C.muted}"/>`;
      s += text(X(v), box.y + box.h + 24, fx(v), { "text-anchor": "middle", "font-size": 15, fill: C.muted });
    });
    s += `<path d="M ${r1(box.x)},${r1(box.y)} V ${r1(box.y + box.h)} H ${r1(box.x + box.w)}" fill="none" stroke="${C.muted}" stroke-width="1.5"/>`;
    if (labels.y) s += text(box.x, box.y - 14, labels.y, { "font-size": 15, "font-weight": 600, fill: labels.yColor || C.muted });
    if (labels.x) s += text(box.x + box.w, box.y + box.h + 46, labels.x, { "text-anchor": "end", "font-size": 15, fill: C.muted });
    return { X, Y, axes: s };
  }
  // a polyline of the points [x, y] through the scales
  const line = (F, xs, ys, color, w = 3, extra = "") =>
    `<polyline points="${xs.map((x, i) => `${r1(F.X(x))},${r1(F.Y(ys[i]))}`).join(" ")}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"${extra}/>`;

  // Colours of the warming stripes (Ed Hawkins): blue to red, from −range to +range
  const STRIPES = ["#08306b", "#08519c", "#2171b5", "#4292c6", "#6baed6", "#9ecae1", "#c6dbef", "#deebf7",
    "#fee0d2", "#fcbba1", "#fc9272", "#fb6a4a", "#ef3b2c", "#cb181d", "#a50f15", "#67000d"];
  function stripe(a, range) {
    const k = Math.max(0, Math.min(STRIPES.length - 1, Math.floor((a + range) / (2 * range) * STRIPES.length)));
    return STRIPES[k];
  }

  R_.series = { colors, series, frame, line, stripe, STRIPES };
})(globalThis);

// ---- src/diagrams/climatology/climogram.js ----
// Climograms (climate diagrams) of the stations of GeoRes.data.climate (dist/climate.js): monthly mean
// temperature (line) and precipitation (bars), on the scale of Walter and Lieth (and Gaussen):
// 10 °C = 20 mm, so a month is dry where the temperature line is above the bar (P < 2T); above
// 100 mm the precipitation scale is compressed ten times (darker bars). Next to the chart: the
// Köppen-Geiger code (GeoRes.koppen) and the key numbers.
//
//   <div class="geores" data-diagram="climogram" data-station="ch-ber"></div>
//   data-station: one station, or two separated by a comma (side by side)
//   data-t, data-p: 12 values each, comma-separated, for a climogram of one's own (data-name, data-place)
//   data-key="false": no Köppen code; data-anon="true": a quiz (letters instead of names, no code),
//   data-first="D": the letter of the first climogram of the quiz (default A)
//   data-compact="true": a narrower drawing (larger text), for a climogram next to a photo
//
// On a web page, the pointer over a month shows its precipitation and temperature in a tooltip, with
// a band across the month (like the Highcharts climograms of GeoApp); also in the sims that use draw.
//
// GeoRes.climate: the stations and the drawing, for the sims (climogram, koppen-key, koppen-map).
// Beyond the stations of dist/climate.js, a data-station can name any station of the WMO normals 1991–2020
// ("wmo-<WMO id>", with dist/climate-wmo.js: {{< geores … stations="wmo" >}}) or one that the page adds:
//   GeoRes.climate.addStations([{ id, name, country, lat, lon, el, source, T: [12 °C], P: [12 mm] }])
//   (name and country: a text, or { en, fr }); the sim climogram also reads them from data-station-src (a JSON file).
(function (G) {
  const R_ = G.GeoRes, { r1, svgDoc, text, esc } = R_.lib;

  R_.addStrings({
    en: {
      cgTemp: "temperature (°C)", cgPrec: "precipitation (mm)", cgMean: "mean", cgRange: "range", cgYear: "per year",
      cgDry: "dry months", cgDryNone: "no dry month", cgDryArea: "dry: P < 2T", cgCompressed: "above 100 mm: 1/10 scale",
      cgMonths: ["J", "F", "M", "A", "M", "J", "J", "A", "S", "O", "N", "D"], cgAlt: "{n} m", cgSource: "normals 1991–2020, {s}",
      cgTitle: "Climogram", cgUnknown: "unknown station", cgTipP: "Precipitation", cgTipT: "Temperature", cgColon: ":",
    },
    fr: {
      cgTemp: "température (°C)", cgPrec: "précipitations (mm)", cgMean: "moyenne", cgRange: "amplitude", cgYear: "par an",
      cgDry: "mois secs", cgDryNone: "aucun mois sec", cgDryArea: "sec : P < 2T", cgCompressed: "au-dessus de 100 mm : échelle 1/10",
      cgMonths: ["J", "F", "M", "A", "M", "J", "J", "A", "S", "O", "N", "D"], cgAlt: "{n} m", cgSource: "normales 1991–2020, {s}",
      cgTitle: "Climatogramme", cgUnknown: "station inconnue", cgTipP: "Précipitations", cgTipT: "Température", cgColon: "\u202f:",
    },
  });

  const PALETTE = {
    dark: { temp: "#ff6a5a", prec: "#5ab0ff", precHi: "#2d6fb8", dry: "rgba(255, 196, 90, 0.45)", dryLine: "#ffc45a", frame: "rgba(255,255,255,0.35)", zero: "rgba(255,255,255,0.55)", band: "rgba(255,255,255,0.1)" },
    light: { temp: "#d63a2b", prec: "#3a8ee0", precHi: "#1f5fa8", dry: "rgba(240, 170, 40, 0.4)", dryLine: "#c98a00", frame: "#9aa3b2", zero: "#5d6575", band: "rgba(204,214,235,0.45)" },
  };
  const stations = () => (R_.data && R_.data.climate && R_.data.climate.stations) || [];
  // every WMO station (dist/climate-wmo.js), unpacked once, without those of dist/climate.js (their names are better)
  let wmo = null;
  function wmoStations() {
    const W = R_.data && R_.data.climateWmo;
    if (!W) return [];
    if (wmo) return wmo;
    const own = new Set(stations().map(s => s.id));
    wmo = W.stations.filter(r => !own.has("wmo-" + r[0])).map(r => {
      const c = W.countries[r[2]] || [r[2], r[2]];
      return { id: "wmo-" + r[0], name: { en: r[1], fr: r[1] }, country: { en: c[0], fr: c[1] }, lat: r[3], lon: r[4], el: r[5],
        source: "WMO", T: r.slice(6, 18), P: r.slice(18, 30) };
    });
    return wmo;
  }
  // the stations a page adds (addStations, data-station-src)
  const added = [];
  function addStations(list) {
    for (const s of [].concat(list || [])) {
      if (!s || !s.id || !Array.isArray(s.T) || !Array.isArray(s.P) || s.T.length !== 12 || s.P.length !== 12) {
        console.warn("GeoRes.climate.addStations: a station needs an id and 12 values of T and P", s);
        continue;
      }
      const t = Object.assign({ source: "" }, s, { T: s.T.map(Number), P: s.P.map(Number) }), i = added.findIndex(x => x.id === s.id);
      if (i >= 0) added[i] = t; else added.push(t);
    }
    return added.length;
  }
  const all = () => stations().concat(added, wmoStations());
  const station = id => stations().find(s => s.id === id) || added.find(s => s.id === id) || wmoStations().find(s => s.id === id) || null;
  const nameOf = (s, L) => (s.name && (s.name[L] || s.name.en)) || s.name || "";
  const countryOf = (s, L) => (s.country && (s.country[L] || s.country.en)) || s.country || "";
  const fmt = (L, x, d = 1) => R_.num(L, x, d);

  // Precipitation (mm) -> temperature units (°C) of the chart: 2 mm per °C up to 100 mm, then 20 mm per °C
  const pUnits = p => (p <= 100 ? p / 2 : 50 + (p - 100) / 20);

  // A climogram in a box {x, y, w, h}; s = { name, place, el, lat, lon, T, P, source }
  function draw(s, box, th, L, opts = {}) {
    const C = Object.assign({}, R_.meteo.colors(th), PALETTE[th.name === "dark" ? "dark" : "light"]);
    const tr = k => R_.t(L, k), T = s.T, P = s.P;
    const key = opts.key !== false && opts.key !== "false";
    const side = key ? Math.min(250, box.w * 0.3) : 0;
    const cx0 = box.x + 62, cx1 = box.x + box.w - side - 62, cy0 = box.y + 92, cy1 = box.y + box.h - 34;
    // temperature axis: from a multiple of 10 below the coldest month (or 0) to at least 30 °C,
    // and high enough for the precipitation
    const tmin = Math.min(0, Math.floor(Math.min(...T) / 10) * 10);
    const tmax = Math.max(30, Math.ceil(Math.max(...T) / 10) * 10, Math.ceil(Math.max(...P.map(pUnits)) / 5) * 5);
    const Y = t => cy1 - (t - tmin) / (tmax - tmin) * (cy1 - cy0);
    const bw = (cx1 - cx0) / 12, X = m => cx0 + (m + 0.5) * bw;
    let out = "";
    // title
    out += text(box.x + 4, box.y + 24, esc(s.name), { "font-size": 26, "font-weight": 700, fill: C.text });
    const sub = [s.place, s.el !== undefined && s.el !== null && s.el !== "" ? tr("cgAlt").replace("{n}", R_.num(L, Math.round(+s.el), 0)) : null,
      s.lat !== undefined ? `${fmt(L, Math.abs(s.lat), 1)}° ${s.lat >= 0 ? "N" : "S"}` : null].filter(Boolean).join(" · ");
    out += text(box.x + 4, box.y + 48, esc(sub), { "font-size": 16, fill: C.muted });
    // grid and axes
    for (let t = tmin; t <= tmax + 0.1; t += 10) {
      const y = r1(Y(t));
      out += `<line x1="${cx0}" x2="${r1(cx1)}" y1="${y}" y2="${y}" stroke="${t === 0 ? C.zero : C.grid}" stroke-width="${t === 0 ? 1.5 : 1}"/>`;
      out += text(cx0 - 8, y + 5, t < 0 ? `−${-t}` : t, { "text-anchor": "end", "font-size": 14, fill: C.temp });
      const pv = t <= 0 ? null : t <= 50 ? 2 * t : 100 + (t - 50) * 20;
      if (pv !== null) out += text(cx1 + 8, y + 5, pv, { "font-size": 14, fill: C.prec });
    }
    if (tmax > 50) out += `<line x1="${cx0}" x2="${r1(cx1)}" y1="${r1(Y(50))}" y2="${r1(Y(50))}" stroke="${C.prec}" stroke-width="1" stroke-dasharray="4 4"/>`;
    out += text(cx0 - 52, cy0 - 14, tr("cgTemp"), { "font-size": 14, "font-weight": 600, fill: C.temp });
    out += text(cx1 + 52, cy0 - 14, tr("cgPrec"), { "text-anchor": "end", "font-size": 14, "font-weight": 600, fill: C.prec });
    // the bands of the months under the pointer (hidden until then)
    for (let m = 0; m < 12; m++) out += `<rect class="cg-band" data-m="${m}" x="${r1(cx0 + m * bw)}" y="${r1(cy0)}" width="${r1(bw)}" height="${r1(cy1 - cy0)}" fill="${C.band}" fill-opacity="0"/>`;
    // bars (dark part above 100 mm), dry months
    let dryArea = "";
    for (let m = 0; m < 12; m++) {
      const x = X(m) - bw * 0.36, w = bw * 0.72, p = P[m];
      const yb = Y(Math.max(tmin, 0)), y100 = Y(Math.min(pUnits(p), 50)), yp = Y(pUnits(p));
      out += `<rect x="${r1(x)}" y="${r1(y100)}" width="${r1(w)}" height="${r1(Math.max(0, yb - y100))}" fill="${C.prec}" fill-opacity="0.85"/>`;
      if (p > 100) out += `<rect x="${r1(x)}" y="${r1(yp)}" width="${r1(w)}" height="${r1(y100 - yp)}" fill="${C.precHi}"/>`;
    }
    // the dry season: where the temperature line is above the precipitation (P < 2T), between the
    // two lines joining the middles of the months
    const tAt = x => { const f = Math.min(11, Math.max(0, (x - X(0)) / bw)), i = Math.min(10, Math.floor(f)), u = f - i; return T[i] * (1 - u) + T[i + 1] * u; };
    const pAt = x => { const f = Math.min(11, Math.max(0, (x - X(0)) / bw)), i = Math.min(10, Math.floor(f)), u = f - i; return pUnits(P[i]) * (1 - u) + pUnits(P[i + 1]) * u; };
    let run = [];
    const flush = () => {
      if (run.length > 1) dryArea += `<polygon points="${run.map(([x, t]) => `${r1(x)},${r1(Y(t))}`).join(" ")} ${run.slice().reverse().map(([x, , p]) => `${r1(x)},${r1(Y(p))}`).join(" ")}" fill="${C.dry}" stroke="${C.dryLine}" stroke-width="1"/>`;
      run = [];
    };
    for (let x = X(0); x <= X(11) + 0.01; x += bw / 16) {
      const t = tAt(x), p = pAt(x);
      if (t > p && t > 0) run.push([x, t, p]); else flush();
    }
    flush();
    out += dryArea;
    // temperature line
    const pts = T.map((t, m) => `${r1(X(m))},${r1(Y(t))}`).join(" ");
    out += `<polyline points="${pts}" fill="none" stroke="${C.temp}" stroke-width="4" stroke-linejoin="round" stroke-linecap="round"/>`;
    T.forEach((t, m) => { out += `<circle class="cg-dot" data-m="${m}" cx="${r1(X(m))}" cy="${r1(Y(t))}" r="4.5" fill="${C.temp}"/>`; });
    tr("cgMonths").forEach((mn, m) => { out += text(X(m), cy1 + 22, mn, { "text-anchor": "middle", "font-size": 15, fill: C.muted }); });
    out += `<rect x="${cx0}" y="${r1(cy0)}" width="${r1(cx1 - cx0)}" height="${r1(cy1 - cy0)}" fill="none" stroke="${C.frame}"/>`;
    // the key numbers and the Köppen code
    if (key) {
      const k = R_.koppen.classify(T, P, { cd: opts.cd }), x = box.x + box.w - side + 16;
      const mean = T.reduce((a, b) => a + b, 0) / 12, range = Math.max(...T) - Math.min(...T), tot = P.reduce((a, b) => a + b, 0);
      const dry = T.filter((t, m) => 2 * t > P[m] && t > 0).length;
      const col = R_.koppen.color(k.code);
      out += `<rect x="${r1(x)}" y="${r1(cy0)}" width="${r1(side - 16)}" height="64" rx="10" fill="${col}"/>`;
      out += text(x + (side - 16) / 2, cy0 + 45, k.code, { "text-anchor": "middle", "font-size": 40, "font-weight": 800, fill: R_.koppen.ink(k.code) });
      const nm = R_.koppen.name(L, k.code);
      // the name on up to two lines
      const words = nm.split(" "), lines = [""];
      words.forEach(w => { const l = lines[lines.length - 1]; if ((l + " " + w).trim().length > 22 && l) lines.push(w); else lines[lines.length - 1] = (l + " " + w).trim(); });
      lines.slice(0, 3).forEach((l, i) => { out += text(x, cy0 + 92 + i * 22, esc(l), { "font-size": 17, "font-weight": 600, fill: C.text }); });
      const y0 = cy0 + 104 + Math.min(3, lines.length) * 22;
      const row = (i, label, value, color) => text(x, y0 + i * 48, label, { "font-size": 14, fill: C.muted }) +
        text(x, y0 + i * 48 + 24, value, { "font-size": 21, "font-weight": 700, fill: color || C.text });
      out += row(0, tr("cgMean"), `${fmt(L, mean)} °C`, C.temp) + row(1, tr("cgRange"), `${fmt(L, range)} °C`, C.temp) +
        row(2, tr("cgYear"), `${R_.num(L, Math.round(tot), 0)} mm`, C.prec) +
        row(3, tr("cgDry"), dry ? String(dry) : tr("cgDryNone"), dry ? (th.name === "dark" ? "#ffc45a" : "#c98a00") : C.text);
    }
    if (s.source) out += text(cx0, cy1 + 44, esc(tr("cgSource").replace("{s}", s.source)), { "font-size": 12, fill: C.muted });
    // the pointer areas of the months, on top (see the tooltip below)
    for (let m = 0; m < 12; m++) out += `<rect class="cg-hit" data-m="${m}" x="${r1(cx0 + m * bw)}" y="${r1(cy0)}" width="${r1(bw)}" height="${r1(cy1 - cy0)}" fill="transparent"/>`;
    return `<g class="cg" data-th="${th.name === "dark" ? "dark" : "light"}" data-lang="${L}" data-t="${T.join(",")}" data-p="${P.join(",")}" data-ct="${C.temp}" data-cp="${C.prec}">${out}</g>`;
  }

  // Tooltip of the climograms on a web page: one element for the page, shown by the pointer over a
  // month (.cg-hit) of any climogram, with the band of the month and a larger temperature dot
  function tooltip(doc) {
    let tip = null, on = null;
    const value = (L, x, d) => R_.num(L, x, d).replace("-", "−");
    const mark = (g, m, show) => {
      g.querySelectorAll(`.cg-band[data-m="${m}"]`).forEach(b => b.setAttribute("fill-opacity", show ? 1 : 0));
      g.querySelectorAll(`.cg-dot[data-m="${m}"]`).forEach(d => d.setAttribute("r", show ? 7 : 4.5));
    };
    const hide = () => {
      if (on) mark(on.g, on.m, false);
      on = null;
      if (tip) tip.hidden = true;
    };
    doc.addEventListener("pointermove", e => {
      const hit = e.target && e.target.closest ? e.target.closest(".cg-hit") : null;
      const g = hit && hit.closest(".cg");
      if (!g) return hide();
      const m = +hit.dataset.m, L = g.dataset.lang, tr = k => R_.t(L, k);
      if (!on || on.g !== g || on.m !== m) {
        hide();
        on = { g, m };
        mark(g, m, true);
        if (!tip) {
          tip = doc.createElement("div");
          tip.className = "geores-tip";
          doc.body.appendChild(tip);
        }
        const t = +g.dataset.t.split(",")[m], p = +g.dataset.p.split(",")[m], month = tr("months")[m];
        const line = (color, label, v) => `<div><span style="color:${color}">●</span> ${label}${tr("cgColon")} <b>${v}</b></div>`;
        tip.innerHTML = `<div class="geores-tip-head">${month[0].toUpperCase() + month.slice(1)}</div>` +
          line(g.dataset.cp, tr("cgTipP"), `${value(L, p, Number.isInteger(p) ? 0 : 1)} mm`) +
          line(g.dataset.ct, tr("cgTipT"), `${value(L, t, 1)} °C`);
        tip.classList.toggle("geores-tip-dark", g.dataset.th === "dark");
        tip.hidden = false;
      }
      // next to the pointer, on the other side near the edges of the window
      const w = tip.offsetWidth, h = tip.offsetHeight, gap = 16;
      const x = e.clientX + gap + w > doc.documentElement.clientWidth ? e.clientX - gap - w : e.clientX + gap;
      const y = Math.max(4, Math.min(e.clientY - h / 2, doc.documentElement.clientHeight - h - 4));
      tip.style.left = `${x}px`;
      tip.style.top = `${y}px`;
    });
    doc.addEventListener("pointerout", e => { if (!e.relatedTarget) hide(); });
    doc.addEventListener("keydown", hide);   // e.g. the next slide of a keynote
  }
  if (typeof document !== "undefined") tooltip(document);

  // A station of the data as the input of draw
  function input(id, L) {
    const s = station(id);
    if (!s) return null;
    return { name: nameOf(s, L), place: countryOf(s, L), el: s.el, lat: s.lat, lon: s.lon, T: s.T, P: s.P, source: s.source };
  }

  R_.diagrams["climogram"] = function (opts = {}) {
    const th = R_.theme(opts.theme), L = opts.lang, tr = k => R_.t(L, k);
    let list = [];
    if (opts.t && opts.p) {
      const T = String(opts.t).split(",").map(Number), P = String(opts.p).split(",").map(Number);
      list = [{ name: opts.name || "", place: opts.place || "", el: opts.el, lat: opts.lat !== undefined ? +opts.lat : undefined, T, P }];
    } else {
      list = String(opts.station || "ch-ber").split(",").map(id => input(id.trim(), L)).filter(Boolean);
    }
    // a quiz: no names, no code
    const anon = opts.anon && opts.anon !== "false";
    if (anon) list = list.map((s, i) => Object.assign({}, s, { name: String.fromCharCode(String(opts.first || "A").toUpperCase().charCodeAt(0) + i), place: "", el: "", lat: undefined, source: "" }));
    if (!list.length) return svgDoc("0 0 800 100", text(20, 50, tr("cgUnknown"), { "font-size": 20 }), th);
    const compact = opts.compact && opts.compact !== "false";
    const W = compact ? 820 : list.length > 1 ? 1280 : 1100, H = 520, w = W / list.length;
    const body = list.map((s, i) => draw(s, { x: i * w + 6, y: 6, w: w - 18, h: H - 30 }, th, L, { key: anon ? false : opts.key, cd: opts.cd })).join("");
    return svgDoc(`0 0 ${W} ${H}`, body, th, { title: `${tr("cgTitle")}: ${list.map(s => s.name).join(", ")}` });
  };

  R_.climate = { stations, all, station, addStations, nameOf, countryOf, input, draw, pUnits };
})(globalThis);

// ---- src/diagrams/climatology/co2-curve.js ----
// The Keeling curve: monthly CO2 at Mauna Loa (NOAA GML) since 1958, with its yearly wave (plants
// of the Northern Hemisphere take up CO2 in summer) and the first and last yearly means.
// Steps: 0 the curve, 1 the values and the yearly wave.
(function (G) {
  const R_ = G.GeoRes, { r1, svgDoc, text } = R_.lib;

  R_.addStrings({
    en: { cc2Title: "CO₂ in the air, Mauna Loa (Hawaii)", cc2Unit: "CO₂ (ppm)", cc2Wave: "every year a wave: plants take up CO₂ in the northern summer", cc2Source: "NOAA Global Monitoring Laboratory", cc2Mean: "{y}: {v} ppm" },
    fr: { cc2Title: "Le CO₂ dans l'air, Mauna Loa (Hawaï)", cc2Unit: "CO₂ (ppm)", cc2Wave: "chaque année une vague : les plantes absorbent du CO₂ pendant l'été boréal", cc2Source: "NOAA Global Monitoring Laboratory", cc2Mean: "{y} : {v} ppm" },
  });

  R_.diagrams["co2-curve"] = function (opts = {}) {
    const th = R_.theme(opts.theme), L = opts.lang, tr = k => R_.t(L, k), S = R_.series, C = S.colors(th), d = S.series();
    if (!d) return svgDoc("0 0 400 60", text(10, 30, "dist/climate.js missing"), th);
    const c = d.co2, last = Math.floor(c.t[c.t.length - 1]);
    const yearMean = y => { const v = c.co2.filter((_, i) => Math.floor(c.t[i]) === y); return v.length === 12 ? v.reduce((a, b) => a + b, 0) / 12 : null; };
    const y1 = yearMean(last) ? last : last - 1, first = 1959, v0 = yearMean(first), v1 = yearMean(y1);
    const F = S.frame(C, { x: 90, y: 50, w: 1130, h: 420 }, [1958, last + 1], [300, 440],
      { x: [1960, 1970, 1980, 1990, 2000, 2010, 2020], y: [300, 320, 340, 360, 380, 400, 420, 440] }, { y: tr("cc2Unit"), yColor: C.co2 }, L);
    let out = F.axes + text(1220, 520, tr("cc2Source"), { "text-anchor": "end", "font-size": 13, fill: C.muted });
    out += R_.meteo.step(opts, 0, S.line(F, c.t, c.co2, C.co2, 2.5));
    const fmt = (y, v) => tr("cc2Mean").replace("{y}", y).replace("{v}", R_.num(L, v, 0));
    out += R_.meteo.step(opts, 1,
      `<circle cx="${r1(F.X(first + 0.5))}" cy="${r1(F.Y(v0))}" r="7" fill="${C.co2}"/>` + text(F.X(first + 0.5) + 14, F.Y(v0) + 30, fmt(first, v0), { "font-size": 22, "font-weight": 700, fill: C.text }) +
      `<circle cx="${r1(F.X(y1 + 0.5))}" cy="${r1(F.Y(v1))}" r="7" fill="${C.co2}"/>` + text(F.X(y1 + 0.5) - 14, F.Y(v1) - 18, fmt(y1, v1), { "text-anchor": "end", "font-size": 22, "font-weight": 700, fill: C.text }) +
      text(F.X(1990), F.Y(395), tr("cc2Wave"), { "font-size": 17, fill: C.muted, "text-anchor": "middle" }));
    return svgDoc("0 0 1280 540", out, th, { title: tr("cc2Title") });
  };
})(globalThis);

// ---- src/diagrams/climatology/glacier-length.js ----
// How far Swiss glacier tongues have retreated since about 1880 (GLAMOS length change, cumulative), for
// a few large glaciers. Steps: one per glacier.
(function (G) {
  const R_ = G.GeoRes, { svgDoc, text } = R_.lib;

  R_.addStrings({
    en: { glTitle: "Glacier tongues retreat", glUnit: "change of length since the first measurement (km)", glSource: "GLAMOS, Glacier Monitoring Switzerland",
      glNames: { "Grosser Aletschgletscher": "Great Aletsch", "Vadret da Morteratsch": "Morteratsch", "Rhonegletscher": "Rhône", "Glacier du Trient": "Trient" } },
    fr: { glTitle: "Les langues glaciaires reculent", glUnit: "changement de longueur depuis la première mesure (km)", glSource: "GLAMOS, Relevés glaciologiques suisses",
      glNames: { "Grosser Aletschgletscher": "Grand Aletsch", "Vadret da Morteratsch": "Morteratsch", "Rhonegletscher": "Rhône", "Glacier du Trient": "Trient" } },
  });

  R_.diagrams["glacier-length"] = function (opts = {}) {
    const th = R_.theme(opts.theme), L = opts.lang, tr = k => R_.t(L, k), S = R_.series, C = S.colors(th), d = S.series();
    if (!d) return svgDoc("0 0 400 60", text(10, 30, "dist/climate.js missing"), th);
    const names = ["Grosser Aletschgletscher", "Vadret da Morteratsch", "Rhonegletscher", "Glacier du Trient"];
    const F = S.frame(C, { x: 100, y: 50, w: 1000, h: 420 }, [1878, 2026], [-3.6, 0.3],
      { x: [1880, 1900, 1920, 1940, 1960, 1980, 2000, 2020], y: [0, -1, -2, -3], yfmt: v => (v < 0 ? "−" : "") + Math.abs(v) }, { y: tr("glUnit") }, L);
    let out = F.axes + text(1100, 540, tr("glSource"), { "text-anchor": "end", "font-size": 13, fill: C.muted });
    names.forEach((n, i) => {
      const g = d.length[n], ys = [g.from].concat(g.year), vs = [0].concat(g.cum.map(v => v / 1000)), col = C.glacier[i];
      const end = vs[vs.length - 1];
      out += R_.meteo.step(opts, i, S.line(F, ys, vs, col, 3.5) +
        text(F.X(ys[ys.length - 1]) + 10, F.Y(end) + 5, `${tr("glNames")[n]} ${R_.num(L, end, 1).replace("-", "−")} km`, { "font-size": 17, "font-weight": 700, fill: col }));
    });
    return svgDoc("0 0 1280 560", out, th, { title: tr("glTitle") });
  };
})(globalThis);

// ---- src/diagrams/climatology/glacier-massbalance.js ----
// Swiss glaciers losing ice (GLAMOS): the cumulative mass balance of three glaciers measured since 1915
// (thickness of ice lost, as metres of water), and the yearly mass balance, averaged over the glaciers
// measured, since 1990. Steps: 0 the long curves, 1 the recent years.
(function (G) {
  const R_ = G.GeoRes, { r1, svgDoc, text } = R_.lib;

  R_.addStrings({
    en: { gmTitle: "Swiss glaciers are melting", gmCum: "ice lost since 1915 (m of water)", gmYear: "each year (m of water), mean of the glaciers measured",
      gmNames: { "Silvrettagletscher": "Silvretta", "Grosser Aletschgletscher": "Great Aletsch", "Claridenfirn": "Clariden" }, gmSource: "GLAMOS, Glacier Monitoring Switzerland", gmRecord: "{y}: {v} m" },
    fr: { gmTitle: "Les glaciers suisses fondent", gmCum: "glace perdue depuis 1915 (m d'eau)", gmYear: "chaque année (m d'eau), moyenne des glaciers mesurés",
      gmNames: { "Silvrettagletscher": "Silvretta", "Grosser Aletschgletscher": "Grand Aletsch", "Claridenfirn": "Clariden" }, gmSource: "GLAMOS, Relevés glaciologiques suisses", gmRecord: "{y} : {v} m" },
  });

  R_.diagrams["glacier-massbalance"] = function (opts = {}) {
    const th = R_.theme(opts.theme), L = opts.lang, tr = k => R_.t(L, k), S = R_.series, C = S.colors(th), d = S.series();
    if (!d) return svgDoc("0 0 400 60", text(10, 30, "dist/climate.js missing"), th);
    const names = ["Silvrettagletscher", "Claridenfirn", "Grosser Aletschgletscher"];
    const cum = names.map(n => { const g = d.massbalance[n]; let s = 0; const ys = [1914], vs = [0]; g.year.forEach((y, i) => { if (y < 1915) return; s += g.ba[i]; ys.push(y); vs.push(s); }); return { n, ys, vs }; });
    const ymax = Math.max(...cum.map(c => c.ys[c.ys.length - 1]));
    const vmin = Math.floor(Math.min(...cum.map(c => Math.min(...c.vs))) / 10) * 10;
    const A = S.frame(C, { x: 90, y: 50, w: 620, h: 420 }, [1914, ymax + 1], [vmin, 5],
      { x: [1920, 1940, 1960, 1980, 2000, 2020], y: [0, -10, -20, -30, -40, -50, -60, -70].filter(v => v >= vmin), yfmt: v => (v < 0 ? "−" : "") + Math.abs(v) }, { y: tr("gmCum") }, L);
    let s0 = A.axes;
    cum.forEach((c, i) => {
      const col = C.glacier[i];
      s0 += S.line(A, c.ys, c.vs, col, 3.5) + text(A.X(c.ys[c.ys.length - 1]) + 8, A.Y(c.vs[c.vs.length - 1]) + 5, tr("gmNames")[c.n], { "font-size": 17, "font-weight": 700, fill: col });
    });
    // the recent years: bars
    const m = d.massbalance_mean, idx = m.year.map((y, i) => i).filter(i => m.year[i] >= 1990);
    const B = S.frame(C, { x: 830, y: 50, w: 400, h: 420 }, [1989, m.year[m.year.length - 1] + 1], [-3.5, 0.5],
      { x: [1990, 2000, 2010, 2020], y: [0, -1, -2, -3], yfmt: v => (v < 0 ? "−" : "") + Math.abs(v) }, { y: tr("gmYear") }, L);
    let s1 = B.axes, rec = idx[0];
    const bw = B.X(1991) - B.X(1990);
    idx.forEach(i => {
      const v = m.ba[i], top = B.Y(Math.max(0, v)), bot = B.Y(Math.min(0, v));
      if (v < m.ba[rec]) rec = i;
      s1 += `<rect x="${r1(B.X(m.year[i]) - bw * 0.4)}" y="${r1(top)}" width="${r1(bw * 0.8)}" height="${r1(bot - top)}" fill="${v < 0 ? C.warm : C.ice}"/>`;
    });
    s1 += text(B.X(m.year[rec]) - 10, B.Y(m.ba[rec]) + 6, tr("gmRecord").replace("{y}", m.year[rec]).replace("{v}", R_.num(L, m.ba[rec], 1)), { "text-anchor": "end", "font-size": 18, "font-weight": 700, fill: C.warm });
    let out = R_.meteo.step(opts, 0, s0) + R_.meteo.step(opts, 1, s1) + text(1230, 540, tr("gmSource"), { "text-anchor": "end", "font-size": 13, fill: C.muted });
    return svgDoc("0 0 1280 560", out, th, { title: tr("gmTitle") });
  };
})(globalThis);

// ---- src/diagrams/climatology/global-temperature.js ----
// The global mean surface temperature since 1850 (HadCRUT5, Met Office), as yearly bars coloured like
// warming stripes, in °C above 1850-1900, with the limits of 1.5 and 2 °C of the Paris Agreement.
// Steps: 0 the bars, 1 the limits.
(function (G) {
  const R_ = G.GeoRes, { r1, svgDoc, text } = R_.lib;

  R_.addStrings({
    en: { gtTitle: "Global temperature since 1850", gtUnit: "°C above 1850–1900", gtParis: "Paris Agreement: well below 2 °C, if possible 1.5 °C", gtSource: "HadCRUT5, Met Office Hadley Centre", gtLast: "{y}: +{v} °C" },
    fr: { gtTitle: "Température mondiale depuis 1850", gtUnit: "°C au-dessus de 1850–1900", gtParis: "Accord de Paris : bien en dessous de 2 °C, si possible 1,5 °C", gtSource: "HadCRUT5, Met Office Hadley Centre", gtLast: "{y} : +{v} °C" },
  });

  R_.diagrams["global-temperature"] = function (opts = {}) {
    const th = R_.theme(opts.theme), L = opts.lang, tr = k => R_.t(L, k), S = R_.series, C = S.colors(th), d = S.series();
    if (!d) return svgDoc("0 0 400 60", text(10, 30, "dist/climate.js missing"), th);
    const g = d.global, n = g.year.length, y0 = g.year[0], y1 = g.year[n - 1];
    const F = S.frame(C, { x: 90, y: 50, w: 1130, h: 420 }, [y0 - 1, y1 + 1], [-0.5, 2.2],
      { x: [1860, 1880, 1900, 1920, 1940, 1960, 1980, 2000, 2020], y: [-0.5, 0, 0.5, 1, 1.5, 2], yfmt: v => (v > 0 ? "+" : v < 0 ? "−" : "") + R_.num(L, Math.abs(v), 1) }, { y: tr("gtUnit") }, L);
    const bw = F.X(y0 + 1) - F.X(y0);
    let bars = "";
    g.year.forEach((y, i) => {
      const a = g.anom[i], top = F.Y(Math.max(a, 0)), bot = F.Y(Math.min(a, 0));
      bars += `<rect x="${r1(F.X(y) - bw * 0.42)}" y="${r1(top)}" width="${r1(bw * 0.84)}" height="${r1(Math.max(1, bot - top))}" fill="${S.stripe(a - 0.6, 0.9)}"/>`;
    });
    let out = F.axes + text(1220, 520, tr("gtSource"), { "text-anchor": "end", "font-size": 13, fill: C.muted });
    out += R_.meteo.step(opts, 0, bars + text(F.X(y1) - 6, F.Y(g.anom[n - 1]) - 14, tr("gtLast").replace("{y}", y1).replace("{v}", R_.num(L, g.anom[n - 1], 2)), { "text-anchor": "end", "font-size": 20, "font-weight": 700, fill: C.text }));
    out += R_.meteo.step(opts, 1, [1.5, 2].map(v => `<line x1="${r1(F.X(y0))}" x2="${r1(F.X(y1))}" y1="${r1(F.Y(v))}" y2="${r1(F.Y(v))}" stroke="${C.warm}" stroke-width="2" stroke-dasharray="8 6"/>`).join("") +
      text(F.X(y0 + 4), F.Y(2) - 10, tr("gtParis"), { "font-size": 18, "font-weight": 600, fill: C.warm }));
    return svgDoc("0 0 1280 540", out, th, { title: tr("gtTitle") });
  };
})(globalThis);

// ---- src/diagrams/climatology/ice-core.js ----
// 800 000 years of climate in the Antarctic ice: the temperature at Dome C (EPICA, Jouzel et al. 2007,
