    if (dark) s += `<rect x="${X0}" y="${ST}" width="${X1 - X0}" height="${SL - ST}" fill="#3a4766"/>`;
    s += `<rect x="${X0}" y="${SL}" width="${X1 - X0}" height="${FL - SL}" fill="${dark ? C.water : "#9cc8ea"}"/>`;
    s += `<rect x="${X0}" y="${FL}" width="${X1 - X0}" height="${CB - FL}" fill="${C.oc}"/>`;
    s += `<rect x="${X0}" y="${CB}" width="${X1 - X0}" height="${LB - CB}" fill="${C.lith}"/>`;
    s += `<rect x="${X0}" y="${LB}" width="${X1 - X0}" height="${BOT - LB}" fill="${C.asth}"/>`;
    // the plume: a column from the deep mantle, a head under the plate
    s += `<path d="M ${XP - 20} ${BOT} C ${XP - 24} ${LB + 50} ${XP - 64} ${LB + 22} ${XP - 84} ${LB + 6} Q ${XP} ${LB - 12} ${XP + 84} ${LB + 6} C ${XP + 64} ${LB + 22} ${XP + 24} ${LB + 50} ${XP + 20} ${BOT} Z" fill="url(#${id}-p)"/>`;
    s += `<line x1="${XP}" y1="${LB}" x2="${XP}" y2="${SL - 50}" stroke="${C.magma}" stroke-width="5"/>`;
