      s += `<path d="M ${x - r - w} ${FL} Q ${x - r * 0.45 - w} ${top + (FL - top) * 0.25} ${x - w} ${top} L ${x + w} ${top} Q ${x + r * 0.45 + w} ${top + (FL - top) * 0.25} ${x + r + w} ${FL} Z" fill="#3e3a38"/>`;
      if (k === "midway") s += `<path d="M ${x - w - 8} ${SL + 1} h ${2 * w + 16} v -5 h -${2 * w + 16} Z" fill="#ebe4cd"/>`;
