    s += `</g><rect x="${X0}" y="${ST}" width="${X1 - X0}" height="${BOT - ST}" fill="none" stroke="${th.ref}" stroke-width="1.2"/>`;
    VOL.forEach(([k, x, h, a, r, kind]) => {
      const top = SL - Math.max(h, 0) - 10;
      s += text(x, top - 20, esc(NM[k]), { "font-size": 16, "font-weight": 700, "text-anchor": "middle" }) + text(x, top, ma(a), { "font-size": 15, "text-anchor": "middle" });
      if (kind) s += text(x, top - 42, esc(kind), { "font-size": 15, "text-anchor": "middle", "font-style": "italic", fill: k === "hawaii" ? HOTC : th.muted, "font-weight": k === "hawaii" ? 700 : 400 });
    });
    s += text(X0 + 12, AY + 6, esc(lab.lith), { "font-size": 16, "font-weight": 700, fill: "#ffffff" });
    s += text(X0 + 310, AY + 36, esc(lab.plate), { "font-size": 16, "font-weight": 700, fill: "#ffffff", "text-anchor": "middle" });
    s += text(X0 + 12, BOT - 14, esc(lab.asth), { "font-size": 16, "font-weight": 700, fill: "#2a1a10" });
    s += text(XP - 30, BOT - 14, esc(lab.plume), { "font-size": 16, "font-weight": 700, fill: "#2a1a10", "text-anchor": "end" });
    s += text(XP, LB + 24, esc(lab.hot), { "font-size": 16, "font-weight": 700, fill: "#2a1a10", "text-anchor": "middle" });

    // the note and the source
    const H = BOT + 30;
    s += text(0, H, esc(tr("hsxAges")), { "font-size": 14, fill: th.muted, "font-style": "italic" });
    s += text(W, H + 22, esc(tr("hsxSource")), { "font-size": 13, fill: th.muted, "text-anchor": "end" });
