    s += `<path d="${plume(1, 0.885, 78, 0.075)}" fill="${RAMP[3][1]}"/><path d="${plume(0.45, 0.885, 50, 0.05)}" fill="${RAMP[4][1]}"/>`;
    // the slabs: the plates go down from the trenches to the core, cold (blue) and warming on the way
