        `<stop offset="0" stop-color="${RAMP[0][1]}"/><stop offset="0.75" stop-color="#3a4a8a"/><stop offset="1" stop-color="${RAMP[1][1]}"/></linearGradient>`;
      s += `<path d="${band(line, t => (t < 0.8 ? 16 + 10 * t : 24 * (1 - 0.6 * (t - 0.8) / 0.2)))}" fill="url(#${id}s${sg > 0 ? "l" : "r"})"/>`;
