    s += `<path d="${poly(path([[0.86, RIDGE - 0.6], [0.92, RIDGE - 2.2], [0.94, RIDGE - 6]], 6))}" fill="none" stroke="#5a2a0a" stroke-width="2.6" marker-end="url(#${id}b)"/>`;

