    for (let lon = W0; lon <= E0; lon += 10) for (const lat of [S, -20, 0, 20, N]) { const [x, y] = F.xy(lon, lat); b0 = [Math.min(b0[0], x), Math.min(b0[1], y), Math.max(b0[2], x), Math.max(b0[3], y)]; }
    const MT = T + 6, K = (W - 2) / (b0[2] - b0[0]), MH = Math.round((b0[3] - b0[1]) * K);
    const P = (lon, lat) => { const [x, y] = F.xy(lon, lat); return [1 + (x - b0[0]) * K, MT + (y - b0[1]) * K]; };
    const rel = lon => ((lon - W0) % 360 + 360) % 360 + W0;   // into W0 .. E0
    // a line or ring of [lon, lat, ...], continuous in longitude, drawn once for each copy (−360, 0, +360) in the map
    const unwrap = flat => { const o = flat.slice(); for (let i = 2; i < o.length; i += 2) { while (o[i] - o[i - 2] > 180) o[i] -= 360; while (o[i] - o[i - 2] < -180) o[i] += 360; } return o; };
    const copies = flat => {
      let mn = 1e9, mx = -1e9; for (let i = 0; i < flat.length; i += 2) { mn = Math.min(mn, flat[i]); mx = Math.max(mx, flat[i]); }
      return [-720, -360, 0, 360, 720].filter(k => mx + k >= W0 && mn + k <= E0);
    };
    const proj = (flat, k) => { const o = []; for (let i = 0; i < flat.length; i += 2) o.push(P(flat[i] + k, flat[i + 1])); return o; };
    // a path through the points, without those less than 1.2 px (Manhattan distance) from the last one kept
    const dOf = (pts, close) => {
      let o = "", lx = 1e9, ly = 1e9;
      pts.forEach(([x, y], i) => { if (i && i < pts.length - 1 && Math.abs(x - lx) + Math.abs(y - ly) < 1.2) return; o += (o ? "L" : "M") + r1(x) + " " + r1(y); lx = x; ly = y; });
      return o + (close ? "Z" : "");
    };

    const id = `pmx${++uid}`;
    // the outline of the map: the meridians of the edges (curved), the parallels S and N (straight)
    const edge = [];
    for (let lat = N; lat >= S; lat -= 1) edge.push(P(W0, lat));
    for (let lat = S; lat <= N; lat += 1) edge.push(P(E0, lat));
    const outline = edge.map(([x, y], i) => (i ? "L" : "M") + r1(x) + " " + r1(y)).join("") + "Z";
    s += `<defs><clipPath id="${id}"><path d="${outline}"/></clipPath></defs><path d="${outline}" fill="${K0.sea}"/><g clip-path="url(#${id})">`;
    // the land (no borders: only the plates matter here)
    let d = "";
    C.forEach(c => c.poly.forEach(poly => poly.forEach(r => { const u = unwrap(r); copies(u).forEach(k => { d += dOf(proj(u, k), true); }); })));
    s += `<path d="${d}" fill="${K0.land}" fill-rule="evenodd" stroke="${K0.land}" stroke-width="0.6"/>`;

    // the earthquakes, under the boundaries: small, a little transparent, the deep ones on top
    const Q = [];
    for (let i = 0; i < D.quakes.length; i += 5) Q.push({ lon: rel(D.quakes[i]), lat: D.quakes[i + 1], d: D.quakes[i + 2], m: D.quakes[i + 3] / 10 });
    Q.sort((a, b) => a.d - b.d || b.m - a.m);
    const rOf = m => 1.3 + (m - 6) * 1.25;
    const cls = dd => (dd < 70 ? 0 : dd < 300 ? 1 : 2);
    let g = "", cur = -1;
