    ["past", "apart", "collision", "together"].forEach(k => {
      s += `<path d="${lines[k]}" fill="none" stroke="${K0[k]}" stroke-width="${k === "past" ? 1.6 : 2.2}" stroke-linejoin="round" stroke-linecap="round"/>`;
      if (tooth[k]) s += `<path d="${tooth[k]}" fill="${K0[k]}"/>`;
    });

