  const R_ = G.GeoRes, { r1 } = R_.lib;

  const STATES = ["DZA", "AGO", "BEN", "BWA", "BFA", "BDI", "CPV", "CMR", "CAF", "TCD", "COM", "COG", "COD", "CIV", "DJI", "EGY",
    "GNQ", "ERI", "SWZ", "ETH", "GAB", "GMB", "GHA", "GIN", "GNB", "KEN", "LSO", "LBR", "LBY", "MDG", "MWI", "MLI", "MRT",
    "MUS", "MAR", "MOZ", "NAM", "NER", "NGA", "RWA", "STP", "SEN", "SYC", "SLE", "SOM", "ZAF", "SSD", "SDN", "TZA", "TGO",
    "TUN", "UGA", "ZMB", "ZWE"];
  const SMALL = ["CPV", "STP", "COM", "MUS", "SYC"];
  // the parts of a state that Natural Earth draws apart: Somaliland with Somalia
  const PART = { SOL: "SOM" };
  const NAMES_FR = { CIV: "Côte d'Ivoire", COD: "RD Congo", COG: "Congo", CAF: "Centrafrique", GNQ: "Guinée équatoriale",
    SSD: "Soudan du Sud", STP: "São Tomé-et-Príncipe", GMB: "Gambie", SWZ: "Eswatini", CPV: "Cap-Vert" };
  const NAMES_EN = { CIV: "Côte d'Ivoire", COD: "DR Congo", COG: "Congo", CAF: "Central African Rep.", GMB: "Gambia", CPV: "Cabo Verde" };
  const LON0 = 20, WEST = -26, EAST = 60, SOUTH = -36, NORTH = 38;

  const countries = () => (R_.data && R_.data.countries) || null;
  const isoOf = c => PART[c.id] || (c.iso && c.iso !== "-99" ? c.iso : c.id);

