    if (!D) return svgDoc("0 0 1000 100", text(20, 50, "dist/countries.js or dist/geopolitics.js missing"), th);
    const W = 1000, T = 92, F = R_.maps.frame("equalearth", { x: 0, y: 0, w: 1000, h: 500 }, 0);
    // the region in the frame, scaled to the width of the map
    const [w, s, e, n] = REGIONS[region].box; let b = [1e9, 1e9, -1e9, -1e9];
    for (let i = 0; i <= 8; i++) for (let j = 0; j <= 8; j++) { const [x, y] = F.xy(w + (e - w) * i / 8, s + (n - s) * j / 8); b = [Math.min(b[0], x), Math.min(b[1], y), Math.max(b[2], x), Math.max(b[3], y)]; }
    const k = W / (b[2] - b[0]), MH = Math.round((b[3] - b[1]) * k), H = T + MH + 34;
