    const inBox = f => f.bbox[0] <= e + 2 && f.bbox[2] >= w - 2 && f.bbox[1] <= n + 2 && f.bbox[3] >= s - 2;
    const d = f => f.poly.map(poly => poly.map(r => { let p = ""; for (let i = 0; i < r.length; i += 2) { const [x, y] = P(r[i], r[i + 1]); p += (i ? "L" : "M") + r1(x) + " " + r1(y); } return p + "Z"; }).join("")).join("");
