    const titled = opts.title !== "false" && opts.title !== false, year = Math.max(1949, Math.min(2026, +opts.year || 2025));
    const NATO = dark ? ["#a9cdf5", "#6fa8e8", "#3f7fcc", "#1f5a9e"] : ["#0b3c78", "#2f6fbf", "#6fa3dc", "#b5d1ef"];
    const CSTO = dark ? "#d68fbd" : "#a95f8f", LAND = dark ? "#2a3349" : "#e8e1d2", SEA = dark ? "#111a2e" : "#f2f6fa", EDGE = dark ? "#111a2e" : "#ffffff";
    const W = 1280, T = titled ? 56 : 0;
