    const bb = box(-30, 84, [33, 50, 71.5]), K = W / (bb[2] - bb[0]), MH = Math.round((bb[3] - bb[1]) * K);
    const P = (lon, lat) => { const [x, y] = F.xy(lon, lat); return [(x - bb[0]) * K, T + 10 + (y - bb[1]) * K]; };
    const ib = box(-128, -52, [24, 50, 72]), IW = 250, IK = IW / (ib[2] - ib[0]), IH = Math.round((ib[3] - ib[1]) * IK), IX = 12, IY = T + 10 + MH - IH - 12;
    const PI_ = (lon, lat) => { const [x, y] = F.xy(lon, lat); return [IX + (x - ib[0]) * IK, IY + (y - ib[1]) * IK]; };
    const id = `ald${++uid}`;
    let s = titled ? text(0, 34, esc(tr("aldTitle")(year)), { "font-size": 28, "font-weight": 700 }) : "";
    s += `<defs><clipPath id="${id}"><rect x="0" y="${T + 10}" width="${W}" height="${MH}"/></clipPath>` +
      `<pattern id="${id}h" width="10" height="10" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="10" height="10" fill="${LAND}"/><rect width="5" height="10" fill="${CSTO}"/></pattern><clipPath id="${id}i"><rect x="${IX}" y="${IY}" width="${IW}" height="${IH}"/></clipPath></defs>` +
      `<rect x="0" y="${T + 10}" width="${W}" height="${MH}" fill="${SEA}"/><g clip-path="url(#${id})">`;
