  const L0 = 70, P1 = 45 * RAD, P2 = 65 * RAD, P0 = 55 * RAD, NN = (Math.sin(P1) + Math.sin(P2)) / 2, CC = Math.cos(P1) ** 2 + 2 * NN * Math.sin(P1);
  const RHO0 = Math.sqrt(CC - 2 * NN * Math.sin(P0)) / NN;
