// ---- src/sims/cartography/projection-types.js ----
// Sim "projection-types": the globe with the surface it is projected on (plane, cone or cylinder)
// and the map that comes out of it. The globe turns (or is dragged) and the map follows: the
// contact line in red is where the map is true to the globe. Follows the page's light/dark theme.
(function (G) {
  const R_ = G.GeoRes, pg = R_.page, { svgDoc } = R_.lib;

  R_.addStrings({
    en: { ptTurn: "Turn the globe", ptDrag: "Drag the globe to turn it.",
      ptAzimuthal: "<b>Azimuthal projection</b>: a plane touches the globe at the North Pole. Around the pole the map is true; the further away, the more it is stretched.",
      ptConic: "<b>Conical projection</b>: a cone touches the globe along the 45th parallel. Along this line the map is true; the cone is then cut open and laid flat.",
      ptCylindrical: "<b>Cylindrical projection</b>: a cylinder touches the globe along the equator. Along the equator the map is true; towards the poles it is stretched." },
    fr: { ptTurn: "Tourner le globe", ptDrag: "Faire glisser le globe pour le tourner.",
      ptAzimuthal: "<b>Projection azimutale</b> : un plan touche le globe au pôle Nord. Autour du pôle la carte est juste ; plus on s'en éloigne, plus elle est étirée.",
      ptConic: "<b>Projection conique</b> : un cône touche le globe le long du 45<sup>e</sup> parallèle. Le long de cette ligne la carte est juste ; le cône est ensuite ouvert et mis à plat.",
      ptCylindrical: "<b>Projection cylindrique</b> : un cylindre touche le globe le long de l'équateur. Le long de l'équateur la carte est juste ; vers les pôles elle est étirée." },
  });

  R_.sims["projection-types"] = function (container, opts = {}) {
    const L = R_.lang(opts.lang), tr = k => R_.t(L, k);
    const TYPES = R_.diagrams["projection-types"].TYPES;
    let type = TYPES[opts.type] ? opts.type : "cylindrical", lon0 = 10, turning = true, dirty = true, since = 1;
    if (G.matchMedia && G.matchMedia("(prefers-reduced-motion: reduce)").matches) turning = false;

    container.classList.add("geores-steps", "geores-wide");
    const figure = document.createElement("div");
    figure.className = "geores-steps-figure geores-drag";
    container.appendChild(figure);
    const panel = pg.controls(container, Object.keys(TYPES).map(k =>
      `<button class="type" data-type="${k}">${tr("type" + TYPES[k].key)}</button>`).join("") +
      `<label><input type="checkbox" class="turn"> ${tr("ptTurn")}</label>`);
    const caption = document.createElement("p");
    caption.className = "geores-steps-text";
    container.appendChild(caption);
    const turn = panel.querySelector(".turn");
    turn.checked = turning;

    function draw() {
      const th = R_.theme(pg.markTheme(container)), T = TYPES[type];
      const body = R_.maps.globe(th, { cx: 210, cy: 215, r: 140, lon0, surface: T.surface, contact: T.contact, stroke: 1.2 }) +
        `<line x1="420" y1="215" x2="468" y2="215" stroke="${th.ref}" stroke-width="3"/>` +
        `<polygon points="482,215 466,206 466,224" fill="${th.ref}"/>` +
        R_.maps.map(T.map, { x: 500, y: 40, w: 480, h: 350 }, th, { lon0, contact: T.contact, stroke: 1.2 });
      figure.innerHTML = svgDoc("0 0 1000 430", body, th, { title: tr("typesTitle") });
      dirty = false;
    }
    function show() {
      panel.querySelectorAll(".type").forEach(b => b.setAttribute("aria-pressed", b.dataset.type === type));
      caption.innerHTML = `${tr("pt" + TYPES[type].key)} ${tr("ptDrag")}`;
      draw();
    }
    panel.querySelectorAll(".type").forEach(b => b.addEventListener("click", () => { type = b.dataset.type; show(); }));
    turn.addEventListener("change", () => { turning = turn.checked; });

    // drag the globe (or the map) to turn it
    let drag = null;
    figure.addEventListener("pointerdown", e => { drag = e.clientX; figure.setPointerCapture(e.pointerId); turning = false; turn.checked = false; });
    figure.addEventListener("pointermove", e => {
      if (drag === null) return;
      const k = 1000 / figure.getBoundingClientRect().width;
      lon0 -= (e.clientX - drag) * k * 0.35;
      drag = e.clientX;
      dirty = true;
    });
    const end = () => { drag = null; };
    figure.addEventListener("pointerup", end);
    figure.addEventListener("pointercancel", end);

    show();
    pg.onThemeChange(draw);
    pg.loop(container, dt => {
      if (turning) { lon0 += 12 * dt; dirty = true; }
      since += dt;
      if (dirty && since > 0.04) { lon0 = ((lon0 + 540) % 360) - 180; since = 0; draw(); }
    });
  };
})(globalThis);

