    const { L, tr, th, ctx, text, wrap, measure, panel } = GE.stage(container, opts, tr => `
      <label><input type="checkbox" class="sg-grid" checked> ${tr("sgxGrid")}</label>
      <label>${tr("sgxMode")} <select class="sg-mode">${Object.entries(tr("sgxModes")).map(([k, s]) => `<option value="${k}">${s}</option>`).join("")}</select></label>
      <button class="sg-next">${tr("sgxNext")}</button><button class="sg-answer">${tr("sgxAnswer")}</button>`);
    const W = GE.W, H = GE.H, S = H / SG.IH, MW = SG.IW * S, PX = MW + 22, PW = W - PX - 8;
    const big = x => SG.big(x, NB), fill = (s, o) => s.replace(/\{(\w+)\}/g, (m, k) => (o[k] !== undefined ? o[k] : m));
