      if (Math.abs(dE) >= 10) p.push(`${big(Math.abs(Math.round(dE / 10) * 10))} m ${dE > 0 ? D.e : D.w}`);
      if (Math.abs(dN) >= 10) p.push(`${big(Math.abs(Math.round(dN / 10) * 10))} m ${dN > 0 ? D.n : D.s}`);
