      const h = lines.reduce((a, l) => a + l.size + 5, 0) + pad;
      const bx = align === "right" ? x - w : align === "center" ? x - w / 2 : x;
      ctx.fillStyle = "rgba(255,255,255,0.93)"; ctx.fillRect(bx, y, w, h);
      let yy = y + pad - 3;
      lines.forEach(l => { yy += l.size + 5; text(l.s, bx + pad, yy - 4, { size: l.size, weight: l.weight || 400, color: l.color || INK }); });
