      Ns.forEach(N => { for (let E = 2598500; E <= 2601700; E += 100) { const [x, y] = toXY(E, N), l = E % 500 ? 4 : 8; ctx.moveTo(x, y - l); ctx.lineTo(x, y + l); } });
