      const b = tag([{ s: tr("sgxOrigin"), size: 15, weight: 700, color: RED }, { s: `E ${big(2600000)} / N ${big(1200000)}`, size: 15, weight: 700 },
        { s: tr("sgxObs"), size: 13 }], x - 16, y - 92, { align: "right" });
