      glow(X(4300), Y(150), 95, 50, 0, "rgba(255, 160, 90, ALPHA)", 0.2);
      glow(X(13000), Y(0.004), 175, 38, 0.3, "rgba(170, 200, 255, ALPHA)", 0.2);
