      pspTilt: "tilt {v}", pspDay: "day {v}", pspUpsideDown: "upside down", pspOnSide: "on its side",
      pspDays: "{n} days", pspSpeed: "Speed", pspGrid: "Grid", pspPerSecond: "1 s = {v}",
