// ---- src/sims/geology/_geology.js ----
// Shared by the geology sims: the stage (a canvas of 1280 × 610, as the weather sims) and a simple
// model of the Earth's interior after PREM (Dziewonski & Anderson 1981), simplified: the layers, and
// the temperature, pressure, density and speed of the P and S waves at a depth.
//
// In a keynote, put the shortcode in a .sim box of the keynote theme ({.sim}): the canvas fills the
// box, sits on the slide's background and takes the colours of the palette (--accent, --muted).
(function (G) {
  const R_ = G.GeoRes, pg = R_.page;
  const W = 1280, H = 610, FONT = "'Fira Sans', sans-serif", RE = 6371;

  R_.addStrings({
    en: {
      gCrust: "crust", gLithMantle: "lithospheric mantle", gAsthenosphere: "asthenosphere", gUpperMantle: "upper mantle",
      gLowerMantle: "lower mantle", gOuterCore: "outer core", gInnerCore: "inner core", gMantle: "mantle", gCore: "core",
      gSolid: "solid", gSoft: "solid but soft", gLiquid: "liquid", gLithosphere: "lithosphere",
    },
    fr: {
      gCrust: "croûte", gLithMantle: "manteau lithosphérique", gAsthenosphere: "asthénosphère", gUpperMantle: "manteau supérieur",
      gLowerMantle: "manteau inférieur", gOuterCore: "noyau externe", gInnerCore: "noyau interne", gMantle: "manteau", gCore: "noyau",
      gSolid: "solide", gSoft: "solide mais mou", gLiquid: "liquide", gLithosphere: "lithosphère",
    },
  });

  // The layers from the surface down: top and bottom depth (km), name, colour, state
  // (a continental crust of 35 km; under the oceans it is about 7 km thick)
  const LAYERS = [
    { top: 0, bottom: 35, key: "gCrust", color: "#8c7560", state: "gSolid" },
    { top: 35, bottom: 100, key: "gLithMantle", color: "#a45d36", state: "gSolid" },
    { top: 100, bottom: 350, key: "gAsthenosphere", color: "#c9692c", state: "gSoft" },
    { top: 350, bottom: 660, key: "gUpperMantle", color: "#b4532a", state: "gSolid" },
    { top: 660, bottom: 2891, key: "gLowerMantle", color: "#8e3a20", state: "gSolid" },
    { top: 2891, bottom: 5150, key: "gOuterCore", color: "#f0902a", state: "gLiquid" },
    { top: 5150, bottom: RE, key: "gInnerCore", color: "#ffd56b", state: "gSolid" },
  ];
  const layerAt = d => LAYERS.find(l => d < l.bottom) || LAYERS[LAYERS.length - 1];

  // Profiles: [depth (km), value]; two points at the same depth make a jump (the value below wins)
  const PROFILES = {
    // °C: 180 °C at the bottom of the Kola borehole (12.3 km), about 5 400 °C at the centre
    temperature: [[0, 15], [12, 180], [35, 550], [100, 1300], [410, 1500], [660, 1650], [2700, 2600], [2891, 3800], [5150, 5100], [RE, 5400]],
    // GPa
    pressure: [[0, 0], [12, 0.33], [35, 1], [100, 3.2], [410, 13.4], [660, 23.8], [2891, 135.8], [5150, 328.9], [RE, 363.9]],
    // g/cm³
    density: [[0, 2.7], [35, 2.9], [35, 3.35], [410, 3.54], [410, 3.72], [660, 3.99], [660, 4.38], [2891, 5.57], [2891, 9.9], [5150, 12.17], [5150, 12.76], [RE, 13.09]],
    // km/s (PREM, simplified)
    vp: [[0, 6.0], [35, 6.6], [35, 8.05], [220, 8.05], [220, 8.56], [410, 8.91], [410, 9.13], [660, 10.27], [660, 10.75], [771, 11.07], [1071, 11.58],
      [1571, 12.29], [2071, 12.9], [2571, 13.48], [2741, 13.68], [2891, 13.72], [2891, 8.06], [3371, 8.7], [3871, 9.3], [4371, 9.75], [4871, 10.1],
      [5150, 10.36], [5150, 11.03], [RE, 11.26]],
    vs: [[0, 3.5], [35, 3.8], [35, 4.45], [220, 4.45], [220, 4.64], [410, 4.77], [410, 4.93], [660, 5.57], [660, 5.95], [771, 6.24], [1071, 6.44],
      [1571, 6.72], [2071, 6.97], [2571, 7.19], [2741, 7.27], [2891, 7.26], [2891, 0], [5150, 0], [5150, 3.5], [RE, 3.67]],
  };
  function at(name, d) {
    const t = PROFILES[name];
    for (let i = 0; i < t.length - 1; i++) {
      const [d0, v0] = t[i], [d1, v1] = t[i + 1];
      if (d >= d0 && d < d1) return v0 + (v1 - v0) * (d - d0) / (d1 - d0);
    }
    return t[t.length - 1][1];
  }

  // The stage of a geology sim: canvas, theme (the palette of the keynote when there is one),
  // strings, text helpers and controls (html: a function of the translation function tr)
  function stage(container, opts, html) {
    const L = R_.lang(opts.lang), tr = k => R_.t(L, k);
    const host = container.closest(".reveal .sim");
    const css = getComputedStyle(container.parentElement || container), v = n => css.getPropertyValue(n).trim();
    const palette = host && v("--accent") ? { accent: v("--accent"), text: css.color, muted: v("--muted") || css.color } : {};
    const th = R_.theme(Object.assign({ base: "dark" }, palette));
    container.classList.add("geores-stage", "geores-geology");
    const ctx = pg.makeCanvas(container, W, H);

    function text(s, x, y, { size = 18, weight = 400, color = th.text, align = "left", base = "alphabetic", italic = false, halo = null } = {}) {
      ctx.font = `${italic ? "italic " : ""}${weight} ${size}px ${FONT}`;
      ctx.textAlign = align;
      ctx.textBaseline = base;
      if (halo) { ctx.strokeStyle = halo; ctx.lineWidth = 4; ctx.lineJoin = "round"; ctx.strokeText(s, x, y); }
      ctx.fillStyle = color;
      ctx.fillText(s, x, y);
    }
    // Text wrapped to maxW, lines lh apart; returns the y below the last line
    function wrap(s, x, y, maxW, lh, o = {}) {
      ctx.font = `${o.italic ? "italic " : ""}${o.weight || 400} ${o.size || 18}px ${FONT}`;
      let line = "";
      s.split(" ").forEach(w => {
        const test = line ? line + " " + w : w;
        if (ctx.measureText(test).width > maxW && line) { text(line, x, y, o); line = w; y += lh; }
        else line = test;
      });
      if (line) text(line, x, y, o);
      return y + lh;
    }
    const measure = (s, size = 18, weight = 400) => { ctx.font = `${weight} ${size}px ${FONT}`; return ctx.measureText(s).width; };

    const panel = pg.controls(container, html(tr));
    if (host) panel.classList.add("sim-controls");
    return { L, tr, th, ctx, text, wrap, measure, panel };
  }

  // Animation loop, with short steps
  const run = (container, step) => pg.loop(container, dt => step(Math.min(dt, 0.05)));

  // Numbers with thin spaces between thousands: 6 371
  const big = (L, x, d = 0) => R_.num(L, x, d).replace(/\B(?=(\d{3})+(?!\d))/g, " ");

  R_.geology = { W, H, RE, FONT, LAYERS, layerAt, PROFILES, at, stage, run, big };
})(globalThis);

// ---- src/sims/geology/alps-collision.js ----
// Sim "alps-collision": how the Alps were made, in a cross-section from the north (Bresse, Jura) to the south (Po
// plain), from 200 million years ago to today. Five moments, each after a published section:
//   today   the section of J. Ragusa (2023, CC BY 4.0, after Thornton et al. 2018): its units and lines, read from the
//           SVG (_alps-section.js), at its own scale;
//   35 Ma   after Steck et al. (2015, Fig. 23, ~34 Ma): under the Southern Alps and Sesia, the Penninic wedge dips south,
//           from the top Tsaté, Zermatt-Saas, Monte Rosa, Antrona; Siviez-Mischabel north of it and under it, below the
//           Dent Blanche lid; Europe dives; the Prealps in front; the molasse sea;
//   65 Ma   after Schmid et al. (1996, Fig. 5a) and Steck et al. (2015, Fig. 23, ~50 Ma): the Piemont ocean dives under
//           the Dent Blanche-Sesia margin of Adria; the Valais basin open;
//   150 Ma  after Steck et al. (2015, Fig. 12): Europe, (Valais not yet open), Briançonnais, Monte Rosa, the Piemont
//           ocean, Dent Blanche-Sesia, Adria;
//   200 Ma  the continent thins and breaks where the Piemont ocean will open.
// The older moments are stacks: in every column, the units from the top down, always in the same order (STACK). From
// one stack to the next, every boundary moves up or down in its column: no gaps, no overlaps. From 35 Ma to today the
// units change their outlines (their two sides, matched point by point); the gaps that open meanwhile show the two
// moments cross-fading. The moments in between are an illustration, not a reconstruction. Markers stay on their rock.
