    const V = norm(opts.view ? opts.view.split(",").map(Number) : [0.55, 0.75, 0.55]);
    const UP = norm([-V[2] * V[0], -V[2] * V[1], 1 - V[2] * V[2]]), RIGHT = cross(UP, V);
    const proj = w => [dot(w, RIGHT), -dot(w, UP)];                    // unit sphere -> screen offset / R
