    // the column: the first 700 km
    const ZX = 520, ZW = 46, ZY0 = 40, ZY1 = 480, ZMAX = 700, zy = d => ZY0 + (ZY1 - ZY0) * d / ZMAX;
    // the slider: squared, for room near the surface
