      if (x >= ZX - 10 && x <= ZX + ZW + 10 && y >= ZY0 - 10 && y <= ZY1 + 10) target = depth = clamp((y - ZY0) / (ZY1 - ZY0) * ZMAX, 0, ZMAX);
