      const at3 = (w, dd) => S(w.map(c => c * rho(dd)));
      const lab = (s, p, o = {}) => text(s, p[0], p[1], Object.assign({ size: 15, weight: 700, align: "center", base: "middle", halo: dark }, o));
      lab(tr("gMantle"), at3(norm([1, 0, 1]), 1500));
      lab(tr("gOuterCore"), at3(norm([0, 1, 1]), 3550), { size: 13 });
      // the inner core is small: its label in the outer core, on the floor of the cut, with a line
      const [ix, iy] = at3(norm([1, 1, 0]), 5950), [lx, ly] = at3(norm([1, 1.6, 0]), 4250);
      ctx.strokeStyle = "rgba(255,255,255,0.8)"; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(lx, ly - 8); ctx.lineTo(ix, iy); ctx.stroke();
      text(tr("gInnerCore"), lx, ly, { size: 13, weight: 700, halo: dark, align: "center", base: "top" });

