      ctx.beginPath(); ctx.arc(px, py, 8, 0, 2 * Math.PI); ctx.fill(); ctx.stroke();
      ctx.fillStyle = "#ffffff"; ctx.strokeStyle = "#d52b1e"; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(sx, sy, 6, 0, 2 * Math.PI); ctx.fill(); ctx.stroke();
      text(tr("edStart"), sx + 12, sy - 10, { size: 15, weight: 700, halo: dark });

