      text(tr("edTitle"), 40, 48, { size: 26, weight: 700 });
      text(`${big(L, d < 100 ? Math.round(d * 10) / 10 : Math.round(d), d < 100 && d % 1 > 0.05 ? 1 : 0)} km`, 40, 108, { size: 46, weight: 700, color: th.accent });
      text(tr("edBelow"), 40, 134, { size: 16, color: th.muted });
      text(tr(layer.key), 40, 176, { size: 26, weight: 700, color: R_.lib.mix(layer.color, "#ffffff", 0.6) });
      text(tr(layer.state), 40 + ctx.measureText(tr(layer.key)).width + 14, 176, { size: 18, color: th.muted });
      const T = at("temperature", d), P = at("pressure", d), D = at("density", d);
      gauge(222, tr("edTemp"), `${big(L, Math.round(T / (T > 100 ? 10 : 1)) * (T > 100 ? 10 : 1))} °C`, T / 6000, "#ff7a3c",
        [[1200 / 6000, tr("edLava")], [5500 / 6000, tr("edSunSurface")]]);
