    const toXY = (x, z) => { const a = 2 * Math.PI * x / LX, r = RCP + (R - RCP) * z; return [CX + r * Math.sin(a), CY - r * Math.cos(a)]; };

    // the strongest plume and slab, followed smoothly (for the steps)
