            ctx.beginPath(); for (let k = 0; k <= 20; k++) { const z = z0 + (z1 - z0) * k / 20, [a, b] = B.S(fx(z), z); k ? ctx.lineTo(a, b - 8) : ctx.moveTo(a, b - 8); } ctx.stroke();
            ctx.fillStyle = "#3a2a1a";
            for (let k = 0; k <= 8; k++) { const z = z0 + (z1 - z0) * k / 8, [a, b] = B.S(fx(z), z); ctx.fillRect(a - 1.5, b - 12, 3, 12); }
