        let i = 1; while (i < cum.length - 1 && cum[i] < s) i++;
        const l = (cum[i] - cum[i - 1]) || 1, k = (s - cum[i - 1]) / l, ux = (P[i][0] - P[i - 1][0]) / l, uy = (P[i][1] - P[i - 1][1]) / l;
        const x = P[i - 1][0] + (P[i][0] - P[i - 1][0]) * k, y = P[i - 1][1] + (P[i][1] - P[i - 1][1]) * k;
