      puffs.forEach(p => { p.y -= dt * 22; p.x += dt * 6; p.r += dt * 8; p.a -= dt * 0.28; ctx.fillStyle = `rgba(170,165,160,${p.a})`; ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, 2 * Math.PI); ctx.fill(); });
