    const { L, tr, th, ctx, text, measure, panel } = GE.stage(container, opts, tr => `
      <label><input type="checkbox" data-layer="bounds"${on.has("bounds") ? " checked" : ""}> ${tr("pmBounds")}</label>
      <label><input type="checkbox" data-layer="quakes"${on.has("quakes") ? " checked" : ""}> ${tr("pmQuakes")}</label>
      <label><input type="checkbox" data-layer="volcanoes"${on.has("volcanoes") ? " checked" : ""}> ${tr("pmVolcanoes")}</label>
      <label><input type="checkbox" data-layer="age"${on.has("age") ? " checked" : ""}> ${tr("pmAge")}</label>
      <button class="centre">${tr(lon0 > 90 ? "pmEurope" : "pmPacific")}</button>`);
    const W = GE.W, H = GE.H, BOX = { x: 10, y: 4, w: W - 20, h: H - 8 };
    if (!D) { text("…", W / 2, H / 2, { align: "center" }); return; }
    panel.querySelectorAll("input[data-layer]").forEach(b => b.addEventListener("change", () => {
      b.checked ? on.add(b.dataset.layer) : on.delete(b.dataset.layer); draw();
    }));
    const centre = panel.querySelector(".centre");
    centre.addEventListener("click", () => { lon0 = lon0 > 90 ? 10 : 150; centre.textContent = tr(lon0 > 90 ? "pmEurope" : "pmPacific"); build(); });

    // the map at this central meridian: basemap (picture), ocean floor ages (picture), projected features
    let F, base = null, landImg = null, ageImg = null, lines = [], quakes = [], volcs = [];
