      lines = [];
      D.bounds.forEach(b => {
        let run = [], prev = null;
        const flush = () => { if (run.length > 1) lines.push({ b, pts: run }); run = []; };
        for (let i = 0; i < b.line.length; i += 2) {
          const l = rel(b.line[i]);
          if (prev !== null && Math.abs(l - prev) > 180) flush();
          run.push(F.xy(l + lon0, b.line[i + 1])); prev = l;
        }
        flush();
      });
