    panel.querySelector(".rc-next").addEventListener("click", () => { stepI = (stepI + 1) % 8; prog = 0; });

    /* ---------------- the landscape ---------------- */
    const zr = x => 0.34 + 0.09 * Math.sin(x / 64) + 0.04 * Math.sin(x / 21 + 1);   // the line of the river
