          const pocket = smooth((fbm(x / 26, y / 14 + 2) - 0.58 + 0.16 * melt) / 0.14), deep = smooth((y - meltTop(x) - 10) / 40);
          const glow = Math.max(pocket * melt, deep * (0.25 + 0.5 * fbm(x / 22, y / 12 + 7))), hot = smooth((glow - 0.55) / 0.45);
          const red = [120 + 40 * melt, 36 + 14 * melt, 22];
