      for (let x = 300; x < xm; x += 6) { ctx.lineWidth = 2 + 1.6 * (x - 300) / (xm - 300); ctx.beginPath(); ctx.moveTo(...S(x, 0)); ctx.lineTo(...S(Math.min(x + 6, xm), 0)); ctx.stroke(); }
      // labels of the scene
      const L = (s, [x, y], o = {}) => text(s, x, y, Object.assign({ size: 14, weight: 700, align: "center", halo: "rgba(20,12,8,0.8)" }, o));
      L(lab.mountains, (([x, y]) => [x, y - 16])(B.S(120, 0.62)));
