    panel.querySelector(".again").addEventListener("click", () => { t = T0; playing = true; pause.textContent = tr("ssPause"); });
    panel.querySelectorAll("input[type=radio]").forEach(r => r.addEventListener("change", () => { rate = +r.value; t = T0; playing = true; pause.textContent = tr("ssPause"); }));

