      text(tr("ssRidge"), CX, y1 + 20, { size: 14, weight: 700, color: "#ff8a6a", align: "center" });
      // distance scale
      [-300, -150, 150, 300].forEach(k => text(`${Math.abs(k)} ${tr("ssKm")}`, kmx(k) + (k > 0 ? -4 : 4), y1 + 20, { size: 12, color: th.muted, align: k > 0 ? "right" : "left" }));
      if (hoverX !== null) {
        const km = (hoverX - CX) * HALF / (X1 - CX), a = ageAt(km);
        ctx.strokeStyle = th.accent; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(hoverX, y0); ctx.lineTo(hoverX, y1); ctx.stroke();
        if (a !== null) {
          const s = tr("ssAge")(R_.num(L, a, 1), Math.round(Math.abs(km))), w = measure(s, 14) + 16;
          const bx = clamp(hoverX - w / 2, X0, X1 - w);
          ctx.fillStyle = "rgba(15,12,10,0.88)"; ctx.fillRect(bx, y0 + 8, w, 26);
          text(s, bx + 8, y0 + 26, { size: 14 });
        }
      }

      // 2. the magnetic profile, measured along a ship's track
      const py = 286, amp = 24;
      text(tr("ssShip"), X0, py - 38, { size: 14, color: th.muted });
      ctx.strokeStyle = "rgba(255,255,255,0.2)"; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(X0, py); ctx.lineTo(X1, py); ctx.stroke();
      ctx.strokeStyle = "#9fd3ff"; ctx.lineWidth = 2; ctx.beginPath();
      let first = true;
