        // the field of the rock under the ship, smoothed over ~20 km (the magnetometer is far above)
        let s = 0, n = 0;
        for (let k = -10; k <= 10; k += 2) { const a = ageAt((x + k - CX) * HALF / (X1 - CX)); if (a !== null) { s += normalAt(t + a) ? 1 : -1; n++; } else n++; }
