      ctx.fillStyle = mgm; ctx.beginPath(); ctx.moveTo(CX - 120, base); ctx.quadraticCurveTo(CX - 20, sy + 60, CX, sy + crust); ctx.quadraticCurveTo(CX + 20, sy + 60, CX + 120, base); ctx.closePath(); ctx.fill();
