        bc.fillStyle = ["#b5523b", "#8c4a36", "#a65a3c"][k % 3]; bc.beginPath(); bc.moveTo(px - w / 2 - 1.5, y - h); bc.lineTo(px, y - h - 5); bc.lineTo(px + w / 2 + 1.5, y - h); bc.closePath(); bc.fill();
