    const pathLL = polys => { const p = new Path2D(); polys.forEach(poly => poly.forEach(r => { for (let i = 0; i < r.length; i += 2) { const [x, y] = ll(r[i], Math.max(r[i + 1], -8)); i ? p.lineTo(x, y) : p.moveTo(x, y); } p.closePath(); })); return p; };
