      bwRegions: { world: "World", europe: "Europe", mideast: "Middle East and North Africa", asia: "South and East Asia", americas: "Americas" },
      bwMotives: { territory: "territory (dispute, demarcation)", security: "security (militants, terrorism)", migration: "migration and smuggling", other: "other" },
      bwBuilt: (a, b) => `built by ${a} on its border with ${b}`, bwFrom: (s, e) => (e ? `built ${s === e ? s : s + "–" + e}` : `begun in ${s}`), bwDest: d => `destroyed in ${d}`,
