      bwRegions: { world: "Monde", europe: "Europe", mideast: "Moyen-Orient et Afrique du Nord", asia: "Asie du Sud et de l'Est", americas: "Amériques" },
      bwMotives: { territory: "territoire (conflit, démarcation)", security: "sécurité (militants, terrorisme)", migration: "migrations et contrebande", other: "autre" },
      bwBuilt: (a, b) => `construit par ${a} à sa frontière avec ${b}`, bwFrom: (s, e) => (e ? `construit ${s === e ? "en " + s : s + "–" + e}` : `commencé en ${s}`), bwDest: d => `détruit en ${d}`,
      bwMotive: m => `motif : ${m}`, bwAdded: "ajouté pour ce cours (après les données), tracé approximatif",
