      const halo = dark ? "rgba(10,16,30,0.85)" : "rgba(255,255,255,0.9)";
      text(tr("cfSource"), MAP.x + MAP.w - 6, MAP.y + MAP.h - 8, { size: 11, align: "right", color: dark ? "#ffffff" : th.text, halo });
      ctx.restore();
