      const i = year - Y0;
      text(tr("cfTitle"), MAP.x + 2, 30, { size: 24, weight: 700, color: th.accent });
      text(tr("cfHint"), MAP.x + 2, 50, { size: 14, color: th.muted });
      text(String(year), W - 52, 44, { size: 40, weight: 700, align: "right" });
      text(tr("cfCount")(total[i], D.wars[i]), W - 160, 44, { size: 18, align: "right" });
      let kx = MAP.x + 14; const ky = MAP.y + MAP.h - 22;
      ctx.fillStyle = dark ? "rgba(10,16,30,0.8)" : "rgba(255,255,255,0.85)"; ctx.fillRect(MAP.x + 6, ky - 16, 560, 28);
      tr("cfKey").forEach((s, k) => { ctx.fillStyle = HOT[k]; ctx.fillRect(kx, ky - 9, 16, 12); text(s, kx + 22, ky + 2, { size: 14 }); kx += 40 + measure(s, 14); });
      // the chart: conflicts per year by type (bars), battle deaths (line)
      const bw = CH.w / N, sy = (CH.h - 6) / maxTotal;
      total.forEach((_, j) => {
        let y = CH.y + CH.h;
        [2, 4, 3, 1].forEach(k => { const v = D.byType[k][j]; if (!v) return; ctx.fillStyle = TYPE[k]; ctx.globalAlpha = Y0 + j <= year ? 1 : 0.25; ctx.fillRect(CH.x + j * bw + 0.5, y - v * sy, bw - 1, v * sy); y -= v * sy; });
      });
      ctx.globalAlpha = 1;
      ctx.strokeStyle = th.text; ctx.lineWidth = 1.6; ctx.beginPath(); let on = false;
      D.deaths.forEach((v, j) => { if (v == null) { on = false; return; } const x = CH.x + (j + 0.5) * bw, y = CH.y + CH.h - v / maxDeaths * (CH.h - 6); on ? ctx.lineTo(x, y) : ctx.moveTo(x, y); on = true; }); ctx.stroke();
      const px = CH.x + (i + 0.5) * bw; ctx.strokeStyle = th.accent; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(px, CH.y - 6); ctx.lineTo(px, CH.y + CH.h + 2); ctx.stroke();
      [1950, 1970, 1990, 2010, Y1].forEach(y => text(String(y), CH.x + (y - Y0 + 0.5) * bw, CH.y + CH.h + 15, { size: 12, align: "center", color: th.muted }));
      text(`${tr("cfPerYear")} (${maxTotal})`, CH.x, CH.y - 8, { size: 12, color: th.muted });
      text(`— ${tr("cfDeaths")}`, CH.x + CH.w, CH.y - 8, { size: 12, align: "right", color: th.text });
      // the types, on the left, above the lower left corner (a keynote's controls)
