      if (D.deaths[i] != null) text(tr("cfD")(Math.round(D.deaths[i]).toLocaleString(L === "fr" ? "fr-CH" : "en-GB").replace(/[,  ]/g, " ")), 300, CH.y + 15, { size: 15, weight: 700 });
