    function inside(rings, x, y) { let inn = false; rings.forEach(r => { for (let a = 0, z = r.length - 1; a < r.length; z = a++) { const [xi, yi] = r[a], [xj, yj] = r[z]; if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) inn = !inn; } }); return inn; }
