  const DRY_UP = "255, 127, 80", WET = "90, 155, 232", DRY_DOWN = "229, 59, 47";
  const COLORS = { warm: "#ff7a5c", cold: "#7fc7ff", sun: "#ffd84a", ir: "#ff6a3d", high: "#5ab0ff", low: "#ff6a5a", DRY_UP, WET, DRY_DOWN };

