    container.appendChild(host);
    const panel = pg.controls(container,
      `<button class="rcr-play">${tr("rcrPlay")}</button>` +
      `<label>${tr("rcrYear")} <input type="range" class="rcr-year" min="1947" max="2024" step="1"></label><span class="rate year"></span>` +
      `<label><input type="checkbox" class="rcr-totals"> ${tr("rcrTotals")}</label>`);
