      const r = s.getBoundingClientRect(), k = 1280 / r.width, x = (e.clientX - r.left) * k, y = (e.clientY - r.top) * k;
      const from = view === "budget" ? D.S0 : D.Y0, n = D.Y1 - from + 1, t = from + Math.floor((x - Lay.X0) / ((Lay.X1 - Lay.X0) / n));
      const h = t >= from && t <= D.Y1 ? { t, x, y } : null;
