// ---- src/sims/urban/_urban.js ----
// Shared by the urban sims (urban-count, world-cities): the world map (Equal Earth on 10° E, 56° S – 78° N) in a box
// of the canvas, the countries of dist/countries.js with the codes of World Urbanization Prospects 2025, the
// colours of the urban shares, and the hit test of a country.
// Data: dist/urban.js (tools/urban-data.R, UN DESA World Urbanization Prospects 2025).
(function (G) {
  const R_ = G.GeoRes;

  // Natural Earth codes (dist/countries.js) that differ from the ISO codes of WUP 2025
  const ALIAS = { SDS: "SSD", SAH: "ESH", KOS: "XKX", PSX: "PSE", SOL: "SOM", CYN: "CYP" };
  const iso = c => ALIAS[c.id] || c.id;

  // Regions for a closer view (west, east, south, north): the megalopolises of Gottmann and Brunet, Switzerland
  const REGIONS = {
    boswash: [-78.6, -69.6, 37.3, 43.0], tokaido: [129.5, 141.5, 32.4, 37.6], banana: [-3.5, 15, 42, 55.5], switzerland: [5.8, 10.6, 45.75, 47.85],
  };
  // A projection of the world (Equal Earth) or of a region (plate carrée corrected for its latitude) into the box
  // MAP {x, y, w, h}; the countries as paths and rings (for the hit test)
  function world(MAP, region) {
    const C = (R_.data && R_.data.countries) || [];
    let P;
    if (REGIONS[region]) {
      const [w, e, so, no] = REGIONS[region], c = Math.cos((so + no) / 2 * Math.PI / 180);
      const K = Math.min(MAP.w / ((e - w) * c), MAP.h / (no - so));
      const OX = MAP.x + (MAP.w - (e - w) * c * K) / 2, OY = MAP.y + (MAP.h - (no - so) * K) / 2;
      P = (lon, lat) => [OX + (lon - w) * c * K, OY + (no - lat) * K];
    } else {
      const F = R_.maps.frame("equalearth", { x: 0, y: 0, w: 1000, h: 500 }, 10);
      let b = [1e9, 1e9, -1e9, -1e9];
      for (let lon = -170; lon <= 190; lon += 10) for (const lat of [-56, -20, 0, 20, 78]) {
        const [x, y] = F.xy(lon > 180 ? lon - 360 : lon, lat);
        b = [Math.min(b[0], x), Math.min(b[1], y), Math.max(b[2], x), Math.max(b[3], y)];
      }
      const K = Math.min(MAP.w / (b[2] - b[0]), MAP.h / (b[3] - b[1]));
      const OX = MAP.x + (MAP.w - (b[2] - b[0]) * K) / 2 - b[0] * K, OY = MAP.y + (MAP.h - (b[3] - b[1]) * K) / 2 - b[1] * K;
      P = (lon, lat) => { const [x, y] = F.xy(lon, lat); return [OX + x * K, OY + y * K]; };
    }
    const countries = C.filter(c => c.id !== "ATA").map(c => {
      const p = new Path2D(), rings = [];
      c.poly.forEach(poly => poly.forEach(r => {
        const o = [];
        for (let i = 0; i < r.length; i += 2) { const q = P(r[i], r[i + 1]); o.push(q); i ? p.lineTo(q[0], q[1]) : p.moveTo(q[0], q[1]); }
        p.closePath(); rings.push(o);
      }));
      return { c, iso: iso(c), path: p, rings };
    });
    const inRegion = (lon, lat) => !REGIONS[region] || (lon >= REGIONS[region][0] && lon <= REGIONS[region][1] && lat >= REGIONS[region][2] && lat <= REGIONS[region][3]);
    return { P, countries, inRegion };
  }

  function inside(rings, x, y) {
    let inn = false;
    rings.forEach(r => { for (let a = 0, z = r.length - 1; a < r.length; z = a++) { const [xi, yi] = r[a], [xj, yj] = r[z]; if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) inn = !inn; } });
    return inn;
  }

  // Five classes of urban share (%), from rural (grey) to urban (orange)
  const CLASSES = [20, 40, 60, 80];
  const SHADES = {
    dark: ["#4a4d53", "#6f6656", "#a67a45", "#e07f30", "#ff5a1f"],
    light: ["#ece8e1", "#f3cf9f", "#eea35a", "#d96b26", "#a8401a"],
  };
  const shade = (th, v) => {
    const s = SHADES[th.name === "light" ? "light" : "dark"];
    return v == null ? null : s[CLASSES.filter(c => v >= c).length];
  };

  const pct = (L, v) => `${R_.num(L, Math.round(v), 0)} %`;
  const nameOf = (c, L) => (L === "fr" ? c.fr : c.en) || c.en;

  R_.urban = { REGIONS, world, inside, CLASSES, SHADES, shade, pct, nameOf, iso };
})(globalThis);

// ---- src/sims/urban/bid-rent.js ----
// Sim "bid-rent": why the centre is expensive (Alonso 1964, after von Thünen). Three uses bid for land: shops and
// offices (who need the most customers: high rent at the centre, falling fast), housing (falling more slowly), farming
// (low, almost flat). At each distance the highest bid wins, so the city is drawn in rings (Burgess). On the left the
// three straight lines of rent against distance from the centre, on the right the city seen from above. Options: the
// cost of transport (cheaper transport: the rings widen, the city spreads), a tram line (along it, getting to the
// centre costs less: housing reaches further, the rings become sectors, as in Hoyt's model), a second centre (a new
// business centre: several nuclei, as in Harris and Ullman's model). Rents in imaginary units.
//   <div class="geores" data-sim="bid-rent" data-tram="false" data-second="false"></div>
(function (G) {
  const R_ = G.GeoRes;

  R_.addStrings({
    en: {
      brTitle: "Who pays most for the land?", brAxisX: "distance from the centre (km)", brAxisY: "rent the user can pay",
      brUses: ["shops and offices", "housing", "farming"], brTransport: "Transport cost", brTram: "a tram line", brSecond: "a second centre",
      brPlan: "The city from above", brWinner: "the highest bid wins the land",
      brNote: { tram: "Along the tram, the centre is closer in time: housing goes further out (sectors).", second: "A second business centre: the city has several nuclei." },
    },
    fr: {
      brTitle: "Qui paie le plus pour le sol ?", brAxisX: "distance au centre (km)", brAxisY: "loyer que l'utilisateur peut payer",
      brUses: ["commerces et bureaux", "logement", "agriculture"], brTransport: "Coût du transport", brTram: "une ligne de tram", brSecond: "un second centre",
      brPlan: "La ville vue d'en haut", brWinner: "l'offre la plus haute gagne le sol",
      brNote: { tram: "Le long du tram, le centre est plus proche en temps : le logement va plus loin (secteurs).", second: "Un second centre d'affaires : la ville a plusieurs noyaux." },
    },
  });

  R_.sims["bid-rent"] = function (container, opts = {}) {
    const GE = R_.geology;
    const { L, tr, th, ctx, text, wrap, panel } = GE.stage(container, opts, tr => `
      <label>${tr("brTransport")} <input class="br-t" type="range" min="0.5" max="1.6" step="0.05" value="1"></label>
      <label><input class="br-tram" type="checkbox"> ${tr("brTram")}</label>
      <label><input class="br-second" type="checkbox"> ${tr("brSecond")}</label>`);
    const W = GE.W, H = GE.H, dark = th.name !== "light";
    const COL = dark ? ["#ff6a2b", "#e3b26b", "#6d8a5e"] : ["#d9561c", "#d6a14f", "#5f8a4f"];
    // the three bids: rent at the centre and fall per km
    const USE = [{ r: 1000, t: 120 }, { r: 500, t: 40 }, { r: 100, t: 2 }];
    const DMAX = 20, RMAX = 1050;
    let k = 1, tram = opts.tram === "true", second = opts.second === "true";
    const TRAM_A = -Math.PI / 6, C2 = { d: 11, a: Math.PI * 0.6 }, C2USE = { r: 700, t: 150 };

    // graph (left) and plan (right)
    const GR = { x: 90, y: 90, w: 520, h: 400 }, PL = { cx: 960, cy: 300, r: 230 };
    const gx = d => GR.x + d / DMAX * GR.w, gy = v => GR.y + GR.h - Math.max(0, v) / RMAX * GR.h;
    const bid = (u, d, f = 1) => USE[u].r - USE[u].t * k * f * d;

    // the winner at a point of the plan (km from the centre, angle)
    function winner(x, y) {
      const d = Math.hypot(x, y), a = Math.atan2(y, x);
      let da = Math.abs(a - TRAM_A); da = Math.min(da, 2 * Math.PI - da);
      const onTram = tram && da < 0.16 && d < DMAX;
      const bids = [bid(0, d), bid(1, d, onTram ? 0.45 : 1), bid(2, d)];
      if (second) {
        const x2 = C2.d * Math.cos(C2.a), y2 = C2.d * Math.sin(C2.a), d2 = Math.hypot(x - x2, y - y2);
        bids[0] = Math.max(bids[0], C2USE.r - C2USE.t * k * d2);
        bids[1] = Math.max(bids[1], 420 - 40 * k * d2);
      }
      let w = 0; bids.forEach((b, i) => { if (b > bids[w]) w = i; });
      return w;
    }

    // the plan as an image of cells, redrawn when the options change
    const N = 150;
    let plan = null;
    function makePlan() {
      const off = document.createElement("canvas"); off.width = N; off.height = N;
      const o = off.getContext("2d"), img = o.createImageData(N, N);
      const rgb = COL.map(c => [1, 3, 5].map(i => parseInt(c.slice(i, i + 2), 16)));
      for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) {
        const x = (i + 0.5 - N / 2) / (N / 2) * DMAX, y = -(j + 0.5 - N / 2) / (N / 2) * DMAX, p = (j * N + i) * 4;
        if (Math.hypot(x, y) > DMAX) { img.data[p + 3] = 0; continue; }
        const c = rgb[winner(x, y)]; img.data[p] = c[0]; img.data[p + 1] = c[1]; img.data[p + 2] = c[2]; img.data[p + 3] = 255;
      }
      o.putImageData(img, 0, 0);
      plan = off;
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      text(tr("brTitle"), 20, 34, { size: 24, weight: 700, color: th.accent });
      // graph: axes
      ctx.strokeStyle = th.muted; ctx.lineWidth = 1.2; ctx.beginPath(); ctx.moveTo(GR.x, GR.y - 10); ctx.lineTo(GR.x, GR.y + GR.h); ctx.lineTo(GR.x + GR.w + 10, GR.y + GR.h); ctx.stroke();
      for (let d = 0; d <= DMAX; d += 5) text(String(d), gx(d), GR.y + GR.h + 20, { size: 14, align: "center", color: th.muted });
      text(tr("brAxisX"), GR.x + GR.w / 2, GR.y + GR.h + 44, { size: 15, align: "center", color: th.muted });
      ctx.save(); ctx.translate(GR.x - 22, GR.y + GR.h / 2); ctx.rotate(-Math.PI / 2); text(tr("brAxisY"), 0, 0, { size: 15, align: "center", color: th.muted }); ctx.restore();
      // the bands of the winner under the axis
      for (let d = 0; d < DMAX; d += 0.05) { ctx.fillStyle = COL[winner(d, 0)]; ctx.fillRect(gx(d), GR.y + GR.h + 1, gx(d + 0.05) - gx(d) + 0.5, 6); }
      // the three bids, the winning stretch bold
      USE.forEach((u, i) => {
        ctx.strokeStyle = COL[i];
        ctx.lineWidth = 2; ctx.setLineDash([6, 5]); ctx.globalAlpha = 0.6;
        ctx.beginPath(); ctx.moveTo(gx(0), gy(bid(i, 0))); ctx.lineTo(gx(DMAX), gy(bid(i, DMAX))); ctx.stroke();
        ctx.setLineDash([]); ctx.globalAlpha = 1; ctx.lineWidth = 6; ctx.beginPath(); let on = false;
        for (let d = 0; d <= DMAX; d += 0.05) { const y = gy(bid(i, d)); if (winner(d, 0) === i) { on ? ctx.lineTo(gx(d), y) : ctx.moveTo(gx(d), y); on = true; } else on = false; }
        ctx.stroke();
      });
      // labels of the lines, at their start
      tr("brUses").forEach((s, i) => text(s, gx(0) + 12, gy(bid(i, 0)) - 10 + (i === 2 ? -6 : 0), { size: 16, weight: 700, color: COL[i] }));
      text(tr("brWinner"), GR.x + GR.w, GR.y - 6, { size: 14, align: "right", color: th.muted });

      // plan
      text(tr("brPlan"), PL.cx, 66, { size: 17, weight: 700, align: "center" });
      if (!plan) makePlan();
      ctx.imageSmoothingEnabled = false;
      ctx.save(); ctx.beginPath(); ctx.arc(PL.cx, PL.cy, PL.r, 0, 2 * Math.PI); ctx.clip();
      ctx.drawImage(plan, PL.cx - PL.r, PL.cy - PL.r, 2 * PL.r, 2 * PL.r); ctx.restore();
      ctx.strokeStyle = th.muted; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(PL.cx, PL.cy, PL.r, 0, 2 * Math.PI); ctx.stroke();
      const P = (d, a) => [PL.cx + d / DMAX * PL.r * Math.cos(a), PL.cy - d / DMAX * PL.r * Math.sin(a)];
      if (tram) { const [x1, y1] = P(DMAX, TRAM_A); ctx.strokeStyle = th.text; ctx.lineWidth = 3; ctx.setLineDash([10, 6]); ctx.beginPath(); ctx.moveTo(PL.cx, PL.cy); ctx.lineTo(x1, y1); ctx.stroke(); ctx.setLineDash([]); }
      const dot = (x, y) => { ctx.beginPath(); ctx.arc(x, y, 6, 0, 2 * Math.PI); ctx.fillStyle = th.text; ctx.fill(); };
      dot(PL.cx, PL.cy);
      if (second) dot(...P(C2.d, C2.a));
      // key and note
      const ky = 548;
      tr("brUses").forEach((s, i) => { ctx.fillStyle = COL[i]; ctx.fillRect(740 + i * 170, ky - 12, 16, 14); text(s, 762 + i * 170, ky, { size: 14 }); });
      const note = tram ? tr("brNote").tram : second ? tr("brNote").second : "";
      if (note) wrap(note, 740, ky + 30, 520, 18, { size: 14, color: th.muted });
    }

    const tk = panel.querySelector(".br-t"), ttram = panel.querySelector(".br-tram"), tsec = panel.querySelector(".br-second");
    ttram.checked = tram; tsec.checked = second;
    const redo = () => { plan = null; draw(); };
    tk.addEventListener("input", () => { k = +tk.value; redo(); });
    ttram.addEventListener("change", () => { tram = ttram.checked; redo(); });
    tsec.addEventListener("change", () => { second = tsec.checked; redo(); });
    draw();
    R_.page.onThemeChange(draw);
  };
})(globalThis);

// ---- src/sims/urban/built-up.js ----
// Sim "built-up": how much built-up land each city dweller uses, 1975–2050 (UN DESA, World Urbanization Prospects 2025,
// from the Global Human Settlement Layer: the surface covered by buildings in the cities of the country, by the Degree
// of Urbanisation, divided by their population). The lines rise almost everywhere: cities spread faster than they grow.
// Projections after 2025 dashed. Click a country in the key to show or hide it.
//   <div class="geores" data-sim="built-up" data-countries="USA,CHE,FRA,CHN,IND,NGA"></div>
// Data: dist/urban.js (countries[ISO].b, tools/urban-data.R).
(function (G) {
  const R_ = G.GeoRes;

  R_.addStrings({
    en: {
      bupTitle: "Built-up land per city dweller", bupAxis: "m² of buildings per inhabitant of the cities",
      bupHint: "The ground covered by buildings in the cities, divided by their population. Click a country to hide or show it.",
      bupWorld: "World", bupProj: "projection", bupNow: "m² in 2025",
      bupNames: { USA: "United States", CHE: "Switzerland", FRA: "France", DEU: "Germany", JPN: "Japan", CHN: "China", BRA: "Brazil", NGA: "Nigeria", IND: "India" },
      bupSource: "UN DESA, World Urbanization Prospects 2025 (Global Human Settlement Layer)",
    },
    fr: {
      bupTitle: "Surface bâtie par citadin", bupAxis: "m² de bâtiments par habitant des villes",
      bupHint: "Le sol couvert de bâtiments dans les villes, divisé par leur population. Cliquez un pays pour le cacher ou le montrer.",
      bupWorld: "Monde", bupProj: "projection", bupNow: "m² en 2025",
      bupNames: { USA: "États-Unis", CHE: "Suisse", FRA: "France", DEU: "Allemagne", JPN: "Japon", CHN: "Chine", BRA: "Brésil", NGA: "Nigeria", IND: "Inde" },
      bupSource: "ONU DESA, World Urbanization Prospects 2025 (Global Human Settlement Layer)",
    },
  });

  R_.sims["built-up"] = function (container, opts = {}) {
    const GE = R_.geology, D = R_.data && R_.data.urban;
    const { L, tr, th, ctx, text, wrap, measure, panel } = GE.stage(container, opts, () => "");
    panel.style.display = "none";   // no controls: the key below is clickable
    const W = GE.W, H = GE.H;
    if (!D) { text("…", W / 2, H / 2, { align: "center" }); return; }
    const dark = th.name !== "light";
    const ALL = ["USA", "JPN", "DEU", "FRA", "CHE", "BRA", "NGA", "CHN", "IND"];
    const COL = dark ? { USA: "#ff6a2b", JPN: "#c49be8", DEU: "#9aa0a8", FRA: "#7fb2e5", CHE: "#ff4f45", BRA: "#7fd1a7", NGA: "#e3b26b", CHN: "#f2c46d", IND: "#6fc4b4" }
      : { USA: "#d9561c", JPN: "#7d4fb0", DEU: "#6b7480", FRA: "#2f6fb0", CHE: "#c41e24", BRA: "#2e8a5e", NGA: "#b8862f", CHN: "#c9a227", IND: "#3a9a8a" };
    let on = new Set((opts.countries || "USA,CHE,FRA,CHN,IND,NGA").split(",").map(s => s.trim()).filter(c => ALL.includes(c)));
    const [Y0, Y1] = D.years, STEP = D.step, A = 1975, NOW = 2025;
    const GR = { x: 90, y: 90, w: 860, h: 430 }, VMAX = 110;
    const X = y => GR.x + (y - A) / (Y1 - A) * GR.w, Yv = v => GR.y + GR.h - v / VMAX * GR.h;
    const series = iso => (iso === "world" ? D.regions.world.b : (D.countries[iso] || {}).b) || [];
    const keys = [];

    function line(vals, col, w) {
      const pts = vals.map((v, i) => [Y0 + i * STEP, v]).filter(([y, v]) => y >= A && v != null);
      [[A, NOW, []], [NOW, Y1, [7, 6]]].forEach(([a, b, dash]) => {
        ctx.setLineDash(dash); ctx.strokeStyle = col; ctx.lineWidth = w; ctx.beginPath();
        pts.filter(([y]) => y >= a && y <= b).forEach(([y, v], k) => (k ? ctx.lineTo(X(y), Yv(v)) : ctx.moveTo(X(y), Yv(v))));
        ctx.stroke();
      });
      ctx.setLineDash([]);
      return pts;
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      text(tr("bupTitle"), 20, 34, { size: 24, weight: 700, color: th.accent });
      wrap(tr("bupHint"), 20, 56, 940, 18, { size: 14, color: th.muted });
      // axes
      ctx.strokeStyle = th.grid; ctx.lineWidth = 1;
      for (let v = 0; v <= 100; v += 20) { ctx.beginPath(); ctx.moveTo(GR.x, Yv(v)); ctx.lineTo(GR.x + GR.w, Yv(v)); ctx.stroke(); text(String(v), GR.x - 10, Yv(v) + 5, { size: 14, align: "right", color: th.muted }); }
      [1975, 2000, 2025, 2050].forEach(y => text(String(y), X(y), GR.y + GR.h + 22, { size: 14, align: "center", color: th.muted }));
      ctx.save(); ctx.translate(GR.x - 52, GR.y + GR.h / 2); ctx.rotate(-Math.PI / 2); text(tr("bupAxis"), 0, 0, { size: 14, align: "center", color: th.muted }); ctx.restore();
      ctx.strokeStyle = th.text; ctx.setLineDash([4, 4]); ctx.beginPath(); ctx.moveTo(X(NOW), GR.y); ctx.lineTo(X(NOW), GR.y + GR.h); ctx.stroke(); ctx.setLineDash([]);
      text(tr("bupProj"), X(NOW) + 6, GR.y + 14, { size: 13, color: th.muted });
      // the world, then the countries; labels at the end, pushed apart
      // the labels at the end of the lines give the value of today (2025), not of the projection
      const ends = [], now = p => (p.find(([y]) => y === NOW) || p[p.length - 1])[1];
      const wp = line(series("world"), th.text, 5); if (wp.length) ends.push({ y: Yv(wp[wp.length - 1][1]), s: `${tr("bupWorld")} ${Math.round(now(wp))}`, col: th.text, b: true });
      ALL.filter(c => on.has(c)).forEach(c => {
        const p = line(series(c), COL[c], 3);
        if (p.length) ends.push({ y: Yv(p[p.length - 1][1]), s: `${tr("bupNames")[c]} ${Math.round(now(p))}`, col: COL[c] });
      });
      ends.sort((a, b) => a.y - b.y); for (let i = 1; i < ends.length; i++) if (ends[i].y - ends[i - 1].y < 18) ends[i].y = ends[i - 1].y + 18;
      ends.forEach(e => text(e.s, GR.x + GR.w + 10, e.y + 5, { size: 14, weight: e.b ? 800 : 600, color: e.col }));
      text(tr("bupNow"), GR.x + GR.w + 10, GR.y - 6, { size: 13, color: th.muted });
      // the key: every country, click to toggle
      keys.length = 0;
      let kx = GR.x;
      ALL.forEach(c => {
        const s = tr("bupNames")[c], w = measure(s, 14) + 34;
        ctx.globalAlpha = on.has(c) ? 1 : 0.35;
        ctx.fillStyle = COL[c]; ctx.fillRect(kx, 560, 18, 12); text(s, kx + 24, 571, { size: 14 });
        ctx.globalAlpha = 1; keys.push([kx, kx + w, c]); kx += w;
      });
      text(tr("bupSource"), W - 14, H - 12, { size: 11, align: "right", color: th.muted });
    }
    const canvas = ctx.canvas;
    canvas.addEventListener("pointerdown", e => {
      const r = canvas.getBoundingClientRect(), x = (e.clientX - r.left) * W / r.width, y = (e.clientY - r.top) * H / r.height;
      if (y < 552 || y > 580) return;
      const k = keys.find(([a, b]) => x >= a && x <= b); if (!k) return;
      on.has(k[2]) ? on.delete(k[2]) : on.add(k[2]); draw();
    });
    draw();
    R_.page.onThemeChange(draw);
  };
})(globalThis);

// ---- src/sims/urban/central-places.js ----
// Sim "central-places": Christaller's central places (1933), the market principle (k = 3). On an even plain, villages
// sit on a triangular grid; every third place is also a town, every ninth also a city. Each level serves a hexagonal
// market area: bread is bought in every village, a doctor is found in the towns, a hospital or a university only in the
// city. Choose a service: its market areas are drawn; a level that offers it also offers everything below.
//   <div class="geores" data-sim="central-places" data-service="town"></div>
(function (G) {
  const R_ = G.GeoRes;

  R_.addStrings({
    en: {
      chrTitle: "Central places", chrService: "Service", chrServices: { village: "bread (every village)", town: "a doctor (towns)", city: "a hospital (the city)" },
      chrKey: ["city", "town", "village"], chrNote: { village: "Small range: people walk to the next village.", town: "Each town serves itself and part of six villages: 3 places' worth (k = 3).", city: "The city serves 9 places' worth: the rare services need many customers." },
      chrAfter: "after Christaller, 1933 (the market principle)",
    },
    fr: {
      chrTitle: "Les lieux centraux", chrService: "Service", chrServices: { village: "du pain (chaque village)", town: "un médecin (les bourgs)", city: "un hôpital (la ville)" },
      chrKey: ["ville", "bourg", "village"], chrNote: { village: "Petite portée : on marche jusqu'au village voisin.", town: "Chaque bourg dessert sa population et une partie de six villages : l'équivalent de 3 lieux (k = 3).", city: "La ville dessert l'équivalent de 9 lieux : les services rares ont besoin de beaucoup de clients." },
      chrAfter: "d'après Christaller, 1933 (principe du marché)",
    },
  });

  R_.sims["central-places"] = function (container, opts = {}) {
    const GE = R_.geology;
    const { L, tr, th, ctx, text, wrap, panel } = GE.stage(container, opts, tr => `
      <label>${tr("chrService")} <select class="chr-s">${Object.entries(tr("chrServices")).map(([k, s]) => `<option value="${k}">${s}</option>`).join("")}</select></label>`);
    const W = GE.W, H = GE.H, dark = th.name !== "light";
    const COL = dark ? { city: "#ff6a2b", town: "#e3b26b", village: "#a9c98f" } : { city: "#d9561c", town: "#d6a14f", village: "#7fa36e" };
    let service = ["village", "town", "city"].includes(opts.service) ? opts.service : "town";
    const d = 58, CX = 470, CY = 320, S3 = Math.sqrt(3);
    // the triangular grid: i·(d, 0) + j·(d/2, d√3/2); towns where (i − j) is a multiple of 3, the city where both are
    const places = [];
    for (let j = -9; j <= 9; j++) for (let i = -14; i <= 14; i++) {
      const x = CX + i * d + j * d / 2, y = CY - j * d * S3 / 2;
      if (x < 20 || x > 920 || y < 60 || y > 590) continue;
      const m3 = n => ((n % 3) + 3) % 3 === 0;
      const level = m3(i) && m3(j) ? "city" : m3(i - j) ? "town" : "village";
      places.push({ x, y, level });
    }
    // a hexagon around (x, y): circumradius r, first vertex at angle a0
    const hex = (x, y, r, a0) => { ctx.beginPath(); for (let k = 0; k < 6; k++) { const a = a0 + k * Math.PI / 3; k ? ctx.lineTo(x + r * Math.cos(a), y + r * Math.sin(a)) : ctx.moveTo(x + r * Math.cos(a), y + r * Math.sin(a)); } ctx.closePath(); };
    // the market areas of each level (Voronoi cells of its grid)
    const AREA = { village: [d / S3, Math.PI / 6], town: [d, 0], city: [d * S3, Math.PI / 6] };
    const rank = { village: 0, town: 1, city: 2 };

    function draw() {
      ctx.clearRect(0, 0, W, H);
      text(tr("chrTitle"), 20, 34, { size: 24, weight: 700, color: th.accent });
      text(tr("chrAfter"), 20, 56, { size: 14, color: th.muted });
      ctx.save(); ctx.beginPath(); ctx.rect(20, 66, 900, 530); ctx.clip();
      // the market areas of the chosen service: every place of that level or higher
      places.filter(p => rank[p.level] >= rank[service]).forEach(p => {
        const [r, a0] = AREA[service];
        hex(p.x, p.y, r, a0); ctx.fillStyle = COL[service]; ctx.globalAlpha = 0.16; ctx.fill(); ctx.globalAlpha = 1;
        ctx.strokeStyle = COL[service]; ctx.lineWidth = 2; ctx.stroke();
      });
      // the places
      places.forEach(p => {
        const r = { village: 4, town: 8, city: 14 }[p.level];
        ctx.beginPath(); ctx.arc(p.x, p.y, r, 0, 2 * Math.PI); ctx.fillStyle = COL[p.level]; ctx.fill();
        ctx.strokeStyle = dark ? "#202226" : "#ffffff"; ctx.lineWidth = 1.5; ctx.stroke();
      });
      ctx.restore();
      // key and note, on the right
      ["city", "town", "village"].forEach((lv, i) => {
        const y = 120 + i * 40, r = { village: 4, town: 8, city: 14 }[lv];
        ctx.beginPath(); ctx.arc(970, y - 6, r, 0, 2 * Math.PI); ctx.fillStyle = COL[lv]; ctx.fill();
        text(tr("chrKey")[i], 1000, y, { size: 18 });
      });
      text(tr("chrServices")[service], 950, 280, { size: 18, weight: 700, color: COL[service] });
      wrap(tr("chrNote")[service], 950, 310, 310, 22, { size: 16 });
    }
    const sel = panel.querySelector(".chr-s");
    sel.value = service;
    sel.addEventListener("change", () => { service = sel.value; draw(); if (container.closest(".reveal")) setTimeout(() => sel.blur(), 0); });
    draw();
    R_.page.onThemeChange(draw);
  };
})(globalThis);

// ---- src/sims/urban/global-cities.js ----
// Sim "global-cities": the world cities of GaWC 2024 (The World According to GaWC, Loughborough University): 332 cities
// ranked by the offices of the big firms of finance, accountancy, consulting, law and advertising that they host, from
// Alpha++ (London, New York) to Sufficiency. On the map, one disc per city, larger and brighter for the higher classes;
// on the right, the number of cities per class and the Swiss cities. Show: Alpha only, Alpha and Beta, or all. Move over
// a city: its class.
//   <div class="geores" data-sim="global-cities" data-show="alpha"></div>
// Data: dist/urban.js (urbanNet.gawc, tools/network-data.R) and dist/countries.js.
(function (G) {
  const R_ = G.GeoRes;

  R_.addStrings({
    en: {
      glcTitle: "Global cities", glcHint: "Ranked by the offices of the big firms of finance, accountancy, consulting, law and advertising.",
      glcShow: "Show", glcShows: { alpha: "Alpha cities", beta: "Alpha and Beta", all: "all classes" }, glcSwiss: "Switzerland",
      glcGroups: ["Alpha++", "Alpha+", "Alpha, Alpha−", "Beta", "Gamma", "Sufficiency"],
      glcSource: "GaWC, The World According to GaWC 2024 (Newcastle, Santa Cruz and Hamilton not placed: several cities possible)",
    },
    fr: {
      glcTitle: "Les villes mondiales", glcHint: "Classées selon les bureaux des grandes firmes de finance, d'audit, de conseil, de droit et de publicité.",
      glcShow: "Montrer", glcShows: { alpha: "les villes Alpha", beta: "Alpha et Beta", all: "toutes les classes" }, glcSwiss: "Suisse",
      glcGroups: ["Alpha++", "Alpha+", "Alpha, Alpha−", "Beta", "Gamma", "Sufficiency"],
      glcSource: "GaWC, The World According to GaWC 2024 (Newcastle, Santa Cruz et Hamilton non placées : plusieurs villes possibles)",
    },
  });

  // the class of GaWC -> group 0–5
  const GROUP = { "Alpha++": 0, "Alpha+": 1, "Alpha": 2, "Alpha-": 2, "Beta+": 3, "Beta": 3, "Beta-": 3, "Gamma+": 4, "Gamma": 4, "Gamma-": 4, "High Sufficiency": 5, "Sufficiency": 5 };

  R_.sims["global-cities"] = function (container, opts = {}) {
    const GE = R_.geology, U = R_.urban, D = R_.data && R_.data.urbanNet;
    const { L, tr, th, ctx, text, measure, panel } = GE.stage(container, opts, tr => `
      <label>${tr("glcShow")} <select class="glc-s">${Object.entries(tr("glcShows")).map(([k, s]) => `<option value="${k}">${s}</option>`).join("")}</select></label>`);
    const W = GE.W, H = GE.H, MAP = { x: 6, y: 62, w: 930, h: 500 };
    if (!D || !R_.data.countries) { text("…", W / 2, H / 2, { align: "center" }); return; }
    let show = ["alpha", "beta", "all"].includes(opts.show) ? opts.show : "alpha", hover = null;
    const dark = th.name !== "light";
    const SEA = dark ? "#202226" : "#f4f6f8", LAND = dark ? "#3a3d43" : "#e6e2da", EDGE = dark ? "#2a2c2f" : "#ffffff";
    const COL = dark ? ["#ff3d1f", "#ff6a2b", "#f2a65e", "#e3c98f", "#9aa0a8", "#6b6e75"] : ["#b8300f", "#d9561c", "#e8913f", "#c9a66b", "#8a8f96", "#b0b4ba"];
    const RAD = [11, 8.5, 6.5, 4.5, 3.3, 2.5];
    const { P, countries } = U.world(MAP);
    const cities = D.gawc.map(([n, c, lat, lon]) => ({ n, c, g: GROUP[c], xy: P(lon, lat) }));
    const maxG = () => (show === "alpha" ? 2 : show === "beta" ? 3 : 5);

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.save(); ctx.beginPath(); ctx.rect(MAP.x, MAP.y, MAP.w, MAP.h); ctx.clip();
      ctx.fillStyle = SEA; ctx.fillRect(MAP.x, MAP.y, MAP.w, MAP.h);
      ctx.fillStyle = LAND; countries.forEach(k => ctx.fill(k.path, "evenodd"));
      ctx.strokeStyle = EDGE; ctx.lineWidth = 0.5; countries.forEach(k => ctx.stroke(k.path));
      // lower classes first, so that the alpha cities are on top
      cities.filter(c => c.g <= maxG()).sort((a, b) => b.g - a.g).forEach(c => {
        ctx.beginPath(); ctx.arc(c.xy[0], c.xy[1], RAD[c.g], 0, 2 * Math.PI); ctx.fillStyle = COL[c.g]; ctx.globalAlpha = 0.85; ctx.fill(); ctx.globalAlpha = 1;
        if (c.g <= 1) { ctx.strokeStyle = dark ? "#ffffff" : "#1d1d1f"; ctx.lineWidth = 1.2; ctx.stroke(); }
      });
      // the two at the top, named
      cities.filter(c => c.g === 0).forEach(c => text(c.n, c.xy[0] + 14, c.xy[1] + 5, { size: 15, weight: 700, color: th.text, halo: SEA }));
      if (hover) { ctx.beginPath(); ctx.arc(hover.c.xy[0], hover.c.xy[1], RAD[hover.c.g] + 3, 0, 2 * Math.PI); ctx.strokeStyle = th.text; ctx.lineWidth = 2; ctx.stroke(); }
      ctx.restore();
      text(tr("glcTitle"), MAP.x + 4, 30, { size: 24, weight: 700, color: th.accent });
      text(tr("glcHint"), MAP.x + 4, 52, { size: 15, color: th.muted });
      // classes and counts, Swiss cities
      const X = 954;
      tr("glcGroups").forEach((s, g) => {
        const y = 90 + g * 34, n = cities.filter(c => c.g === g).length, on = g <= maxG();
        ctx.globalAlpha = on ? 1 : 0.35;
        ctx.beginPath(); ctx.arc(X + 10, y - 6, RAD[g], 0, 2 * Math.PI); ctx.fillStyle = COL[g]; ctx.fill();
        text(s, X + 30, y, { size: 16 }); text(String(n), W - 20, y, { size: 16, weight: 700, align: "right" });
        ctx.globalAlpha = 1;
      });
      text(tr("glcSwiss"), X, 330, { size: 17, weight: 700, color: th.accent });
      // the Swiss cities in the list (Lugano is not)
      ["Zurich", "Geneva", "Basel", "Bern", "Lausanne", "Lugano"].map(n => cities.find(x => x.n === n)).filter(Boolean).forEach((c, i) => {
        text(c.n, X, 360 + i * 26, { size: 16 }); text(c.c, W - 20, 360 + i * 26, { size: 16, weight: 700, align: "right", color: COL[c.g] });
      });
      text(tr("glcSource"), MAP.x + MAP.w - 6, MAP.y + MAP.h + 18, { size: 11, align: "right", color: th.muted });
      if (hover) {
        const s = `${hover.c.n} · ${hover.c.c}`, w = measure(s, 15, 700) + 20;
        let x = hover.x + 14, y = hover.y + 14; if (x + w > W - 4) x = hover.x - 14 - w;
        ctx.fillStyle = "rgba(20,22,26,0.94)"; ctx.fillRect(x, y, w, 28); text(s, x + 10, y + 19, { size: 15, weight: 700, color: "#ffffff" });
      }
    }
    const canvas = ctx.canvas, pos = e => { const r = canvas.getBoundingClientRect(); return [(e.clientX - r.left) * W / r.width, (e.clientY - r.top) * H / r.height]; };
    canvas.addEventListener("pointermove", e => {
      const [x, y] = pos(e); let best = null, bd = 1e9;
      cities.filter(c => c.g <= maxG()).forEach(c => { const dd = Math.hypot(c.xy[0] - x, c.xy[1] - y) - RAD[c.g]; if (dd < bd) { bd = dd; best = c; } });
      hover = best && bd < 4 ? { c: best, x, y } : null; draw();
    });
    canvas.addEventListener("pointerleave", () => { hover = null; draw(); });
    const sel = panel.querySelector(".glc-s");
    sel.value = show;
    sel.addEventListener("change", () => { show = sel.value; draw(); if (container.closest(".reveal")) setTimeout(() => sel.blur(), 0); });
    draw();
    R_.page.onThemeChange(draw);
  };
})(globalThis);

// ---- src/sims/urban/rank-size.js ----
// Sim "rank-size": the cities of a country ranked by population (UN DESA, World Urbanization Prospects 2025, cities by
// the Degree of Urbanisation: 50 000 people or more at 1 500 per km²), on logarithmic axes, against the rank-size rule
// (Zipf: the city of rank r has 1/r of the largest). A "primate city" (Paris, London, Tokyo) stands far above the line;
// a flat hierarchy (Switzerland, Germany, Italy, India, Nigeria) has its largest city below it. On the right, the five largest.
//   <div class="geores" data-sim="rank-size" data-country="FRA"></div>
// Data: dist/urban.js (urbanNet.ranks, tools/network-data.R).
(function (G) {
  const R_ = G.GeoRes;

  R_.addStrings({
    en: {
      rkTitle: "Rank and size", rkCountry: "Country", rkRank: "rank of the city", rkPop: "population (thousands)",
      rkZipf: "rank-size rule: the 2nd city has 1/2 of the 1st, the 3rd 1/3…", rkTimes: n => `the largest is ${n} times the second`,
      rkCount: n => `${n} cities of 50 000 or more`,
      rkNames: { CHE: "Switzerland", FRA: "France", GBR: "United Kingdom", DEU: "Germany", ITA: "Italy", USA: "United States", JPN: "Japan", NGA: "Nigeria", IND: "India", BRA: "Brazil" },
      rkSource: "UN DESA, World Urbanization Prospects 2025 (cities by the Degree of Urbanisation, 2025)",
    },
    fr: {
      rkTitle: "Rang et taille", rkCountry: "Pays", rkRank: "rang de la ville", rkPop: "population (milliers)",
      rkZipf: "règle rang-taille : la 2e ville a 1/2 de la 1re, la 3e 1/3…", rkTimes: n => `la plus grande vaut ${n} fois la deuxième`,
      rkCount: n => `${n} villes de 50 000 habitants ou plus`,
      rkNames: { CHE: "Suisse", FRA: "France", GBR: "Royaume-Uni", DEU: "Allemagne", ITA: "Italie", USA: "États-Unis", JPN: "Japon", NGA: "Nigeria", IND: "Inde", BRA: "Brésil" },
      rkSource: "ONU DESA, World Urbanization Prospects 2025 (villes selon le degré d'urbanisation, 2025)",
    },
  });

  R_.sims["rank-size"] = function (container, opts = {}) {
    const GE = R_.geology, D = R_.data && R_.data.urbanNet;
    const { L, tr, th, ctx, text, panel } = GE.stage(container, opts, tr => `
      <label>${tr("rkCountry")} <select class="rk-c">${Object.entries(tr("rkNames")).map(([k, s]) => `<option value="${k}">${s}</option>`).join("")}</select></label>`);
    const W = GE.W, H = GE.H;
    if (!D) { text("…", W / 2, H / 2, { align: "center" }); return; }
    let iso = D.ranks[opts.country] ? opts.country : "FRA";
    const G_ = { x: 110, y: 70, w: 640, h: 420 }, RMAX = 1000, PMIN = 40, PMAX = 50000;
    const lx = r => G_.x + Math.log10(r) / Math.log10(RMAX) * G_.w;
    const ly = p => G_.y + G_.h - (Math.log10(p) - Math.log10(PMIN)) / (Math.log10(PMAX) - Math.log10(PMIN)) * G_.h;
    const n0 = v => R_.num(L, v, 0).replace(/\B(?=(\d{3})+(?!\d))/g, " ");

    function draw() {
      ctx.clearRect(0, 0, W, H);
      const c = D.ranks[iso] || [];
      text(`${tr("rkTitle")}: ${tr("rkNames")[iso]}`, 20, 34, { size: 24, weight: 700, color: th.accent });
      // axes with decades
      ctx.strokeStyle = th.grid; ctx.lineWidth = 1;
      [1, 10, 100, 1000].forEach(r => { ctx.beginPath(); ctx.moveTo(lx(r), G_.y); ctx.lineTo(lx(r), G_.y + G_.h); ctx.stroke(); text(String(r), lx(r), G_.y + G_.h + 20, { size: 14, align: "center", color: th.muted }); });
      [100, 1000, 10000].forEach(p => { ctx.beginPath(); ctx.moveTo(G_.x, ly(p)); ctx.lineTo(G_.x + G_.w, ly(p)); ctx.stroke(); text(n0(p), G_.x - 8, ly(p) + 5, { size: 14, align: "right", color: th.muted }); });
      text(tr("rkRank"), G_.x + G_.w / 2, G_.y + G_.h + 44, { size: 15, align: "center", color: th.muted });
      ctx.save(); ctx.translate(G_.x - 70, G_.y + G_.h / 2); ctx.rotate(-Math.PI / 2); text(tr("rkPop"), 0, 0, { size: 15, align: "center", color: th.muted }); ctx.restore();
      if (!c.length) return;
      // the rank-size line from the largest city
      const p1 = c[0][1];
      ctx.strokeStyle = th.muted; ctx.setLineDash([7, 6]); ctx.lineWidth = 2; ctx.beginPath();
      ctx.moveTo(lx(1), ly(p1)); ctx.lineTo(lx(Math.min(RMAX, p1 / PMIN)), ly(Math.max(PMIN, p1 / Math.min(RMAX, p1 / PMIN)))); ctx.stroke(); ctx.setLineDash([]);
      text(tr("rkZipf"), G_.x + G_.w, G_.y - 10, { size: 13, align: "right", color: th.muted });
      // the cities
      c.forEach(([n, p], i) => {
        if (i + 1 > RMAX || p < PMIN) return;
        ctx.beginPath(); ctx.arc(lx(i + 1), ly(p), i < 5 ? 6 : 3.5, 0, 2 * Math.PI); ctx.fillStyle = i ? th.text : th.accent; ctx.globalAlpha = i < 5 ? 1 : 0.6; ctx.fill(); ctx.globalAlpha = 1;
      });
      // the five largest, on the right
      const X = 800;
      text(tr("rkCount")(c.length), X, 96, { size: 16, color: th.muted });
      c.slice(0, 5).forEach(([n, p], i) => {
        const y = 140 + i * 50;
        text(`${i + 1}. ${n}`, X, y, { size: 19, weight: i ? 400 : 700, color: i ? th.text : th.accent });
        text(n0(p), W - 30, y, { size: 19, weight: 700, align: "right" });
        ctx.fillStyle = i ? th.muted : th.accent; ctx.globalAlpha = 0.5; ctx.fillRect(X, y + 8, (W - 30 - X) * p / p1, 6); ctx.globalAlpha = 1;
      });
      if (c[1]) text(tr("rkTimes")(R_.num(L, p1 / c[1][1], 1)), X, 420, { size: 18, weight: 700, color: th.accent });
      text(tr("rkSource"), W - 14, H - 12, { size: 11, align: "right", color: th.muted });
    }
    const sel = panel.querySelector(".rk-c");
    sel.value = iso;
    sel.addEventListener("change", () => { iso = sel.value; draw(); if (container.closest(".reveal")) setTimeout(() => sel.blur(), 0); });
    draw();
    R_.page.onThemeChange(draw);
  };
})(globalThis);

// ---- src/sims/urban/time-travel.js ----
// Sim "time-travel": a Swiss town then and now, with swisstopo's maps (journey through time, ch.swisstopo.zeitreihen:
// the national maps of every year since 1844) on the left of a swipe line, and today's map or aerial photo on the
// right. Drag the line to compare, drag the map to move, + and − to zoom; choose the year and the place. The tiles come
// from wmts.geo.admin.ch when the page is open (© swisstopo, free use with the source mentioned; needs the internet).
//   <div class="geores" data-sim="time-travel" data-place="neuchatel" data-year="1880"></div>
//   data-place: neuchatel (default), chauxdefonds, valderuz (the villages that grew with commuting);  data-right: map (default) or photo
(function (G) {
  const R_ = G.GeoRes;

  R_.addStrings({
    en: {
      ttPlace: "Place", ttYear: "Year", ttToday: "Today", ttRight: "Right", ttMap: "map", ttPhoto: "aerial photo",
      ttPlaces: { neuchatel: "Neuchâtel", chauxdefonds: "La Chaux-de-Fonds", valderuz: "Val-de-Ruz" }, ttHint: "Drag the line to compare, drag the map to move.",
      ttSource: "© swisstopo (journey through time; national map; SWISSIMAGE)", ttOffline: "The maps of swisstopo need the internet.",
    },
    fr: {
      ttPlace: "Lieu", ttYear: "Année", ttToday: "Aujourd'hui", ttRight: "À droite", ttMap: "carte", ttPhoto: "photo aérienne",
      ttPlaces: { neuchatel: "Neuchâtel", chauxdefonds: "La Chaux-de-Fonds", valderuz: "Val-de-Ruz" }, ttHint: "Tirez la ligne pour comparer, tirez la carte pour la déplacer.",
      ttSource: "© swisstopo (voyage dans le temps ; carte nationale ; SWISSIMAGE)", ttOffline: "Les cartes de swisstopo demandent internet.",
    },
  });

  const PLACES = { neuchatel: { lat: 46.9915, lon: 6.9290, z: 15 }, chauxdefonds: { lat: 47.1015, lon: 6.8280, z: 15 }, valderuz: { lat: 47.050, lon: 6.890, z: 14 } };
  const URL = {
    old: (y, z, x, t) => `https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.zeitreihen/default/${y}1231/3857/${z}/${x}/${t}.png`,
    map: (z, x, t) => `https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.pixelkarte-farbe/default/current/3857/${z}/${x}/${t}.jpeg`,
    photo: (z, x, t) => `https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.swissimage-product/default/current/3857/${z}/${x}/${t}.jpeg`,
  };

  R_.sims["time-travel"] = function (container, opts = {}) {
    const GE = R_.geology;
    const { L, tr, th, ctx, text, panel } = GE.stage(container, opts, tr => `
      <label>${tr("ttPlace")} <select class="tt-place">${Object.entries(tr("ttPlaces")).map(([k, s]) => `<option value="${k}">${s}</option>`).join("")}</select></label>
      <label>${tr("ttYear")} <input class="tt-year" type="range" min="1850" max="2021" step="1"></label>
      <label>${tr("ttRight")} <select class="tt-right"><option value="map">${tr("ttMap")}</option><option value="photo">${tr("ttPhoto")}</option></select></label>
      <button class="tt-in">+</button><button class="tt-out">−</button>`);
    const W = GE.W, H = GE.H, VIEW = { x: 0, y: 0, w: W, h: H };
    let place = PLACES[opts.place] ? opts.place : "neuchatel", year = Math.max(1850, Math.min(2021, +opts.year || 1880));
    let right = opts.right === "photo" ? "photo" : "map", z = PLACES[place].z, split = Math.round(W * 0.62);
    // the centre of the view, in pixels of the whole world at zoom z
    const world = (lat, lon, zz) => { const n = 256 * 2 ** zz, s = Math.sin(lat * Math.PI / 180); return [(lon + 180) / 360 * n, (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * n]; };
    let [cx, cy] = world(PLACES[place].lat, PLACES[place].lon, z);
    const cache = new Map();
    let failed = 0;
    const tile = url => {
      let im = cache.get(url);
      if (!im) {
        im = new Image();
        im.onload = () => draw(); im.onerror = () => { failed++; draw(); };
        im.src = url; cache.set(url, im);
        if (cache.size > 900) cache.delete(cache.keys().next().value);
      }
      return im;
    };

    function layer(urlOf, x0, x1) {
      ctx.save(); ctx.beginPath(); ctx.rect(x0, VIEW.y, x1 - x0, VIEW.h); ctx.clip();
      const left = cx - W / 2, top = cy - H / 2, n = 2 ** z;
      for (let ty = Math.floor(top / 256); ty <= Math.floor((top + H) / 256); ty++) {
        if (ty < 0 || ty >= n) continue;
        for (let tx = Math.floor((left + x0) / 256); tx <= Math.floor((left + x1) / 256); tx++) {
          const im = tile(urlOf(z, ((tx % n) + n) % n, ty));
          if (im.complete && im.naturalWidth) ctx.drawImage(im, tx * 256 - left, ty * 256 - top, 256, 256);
        }
      }
      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = th.name === "light" ? "#eeeeee" : "#2a2c2f"; ctx.fillRect(0, 0, W, H);
      layer((zz, x, y) => URL.old(year, zz, x, y), 0, split);
      layer((zz, x, y) => URL[right](zz, x, y), split, W);
      // the swipe line and its handle
      ctx.fillStyle = "#ffffff"; ctx.fillRect(split - 2, 0, 4, H);
      ctx.beginPath(); ctx.arc(split, H / 2, 18, 0, 2 * Math.PI); ctx.fillStyle = th.accent; ctx.fill();
      text("◀ ▶", split, H / 2 + 5, { size: 14, weight: 700, align: "center", color: "#1d1d1f" });
      // labels with a dark band
      const band = (x, w) => { ctx.fillStyle = "rgba(20,22,26,0.78)"; ctx.fillRect(x, 10, w, 40); };
      const lt = String(year), rt = `${tr("ttToday")} · ${right === "map" ? tr("ttMap") : tr("ttPhoto")}`;
      band(10, Math.min(split - 20, 120)); text(lt, 20, 40, { size: 26, weight: 700, color: "#ffffff" });
      ctx.font = "700 20px 'Fira Sans', sans-serif"; const rw = ctx.measureText(rt).width + 24;
      band(W - 10 - rw, rw); text(rt, W - 22, 37, { size: 20, weight: 700, align: "right", color: "#ffffff" });
      ctx.fillStyle = "rgba(20,22,26,0.7)"; ctx.fillRect(W - 470, H - 26, 466, 22);
      text(tr("ttSource"), W - 10, H - 10, { size: 12, align: "right", color: "#ffffff" });
      if (failed > 6 && ![...cache.values()].some(im => im.complete && im.naturalWidth)) text(tr("ttOffline"), W / 2, H / 2 - 40, { size: 20, align: "center", color: th.text });
    }

    // drag: the handle moves the line, elsewhere the map moves
    const canvas = ctx.canvas, pos = e => { const r = canvas.getBoundingClientRect(); return [(e.clientX - r.left) * W / r.width, (e.clientY - r.top) * H / r.height]; };
    let drag = null;
    canvas.addEventListener("pointerdown", e => {
      const [x, y] = pos(e);
      drag = Math.abs(x - split) < 26 ? { kind: "split" } : { kind: "pan", x, y, cx, cy };
      canvas.setPointerCapture(e.pointerId); e.preventDefault();
    });
    canvas.addEventListener("pointermove", e => {
      if (!drag) return;
      const [x, y] = pos(e);
      if (drag.kind === "split") split = Math.max(40, Math.min(W - 40, x));
      else { cx = drag.cx - (x - drag.x); cy = drag.cy - (y - drag.y); }
      draw();
    });
    const end = () => { drag = null; };
    canvas.addEventListener("pointerup", end); canvas.addEventListener("pointercancel", end);
    canvas.style.cursor = "grab";

    const sp = panel.querySelector(".tt-place"), sy = panel.querySelector(".tt-year"), sr = panel.querySelector(".tt-right");
    sp.value = place; sy.value = year; sr.value = right;
    const blur = el => { if (container.closest(".reveal")) setTimeout(() => el.blur(), 0); };
    const zoom = d => { const nz = Math.max(13, Math.min(17, z + d)); if (nz === z) return; const f = 2 ** (nz - z); cx *= f; cy *= f; z = nz; draw(); };
    sp.addEventListener("change", () => { place = sp.value; z = PLACES[place].z; [cx, cy] = world(PLACES[place].lat, PLACES[place].lon, z); draw(); blur(sp); });
    sy.addEventListener("input", () => { year = +sy.value; draw(); });
    sr.addEventListener("change", () => { right = sr.value; draw(); blur(sr); });
    panel.querySelector(".tt-in").addEventListener("click", () => zoom(1));
    panel.querySelector(".tt-out").addEventListener("click", () => zoom(-1));
    draw();
    R_.page.onThemeChange(draw);
  };
})(globalThis);

// ---- src/sims/urban/urban-count.js ----
// Sim "urban-count": how urban is each country? Two ways to count (UN DESA, World Urbanization Prospects 2025):
// each country's own definition of "urban", or the same rule for every country (the Degree of Urbanisation: a city is
// at least 50 000 people living at 1 500 per km² or more, a town at least 5 000 at 300 per km² or more). The map shows
// the share of the population that is urban (own definition), in cities and towns, or in cities only, from 1950 to
// 2050; below, the world. Move over a country: both counts.
//   <div class="geores" data-sim="urban-count" data-mode="own" data-year="2025"></div>
//   data-mode: own (default), common (cities and towns), cities (cities only)
// Data: dist/urban.js (tools/urban-data.R) and dist/countries.js.
(function (G) {
  const R_ = G.GeoRes;

  R_.addStrings({
    en: {
      ucTitle: "How urban is each country?", ucPlay: "Play", ucPause: "Pause", ucYear: "Year", ucCount: "Count",
      ucModes: { own: "each country's own definition", common: "same rule: cities and towns", cities: "same rule: cities only" },
      ucHead: { own: "Share urban, by each country's own definition", common: "Share living in cities or towns, by the same rule everywhere", cities: "Share living in cities, by the same rule everywhere" },
      ucRule: "Same rule (UN Degree of Urbanisation): a city has 50 000 people or more at 1 500 per km² or more; a town 5 000 or more at 300 per km² or more.",
      ucWorld: "World", ucCities: "cities", ucTowns: "towns", ucRural: "rural", ucUrban: "urban",
      ucOwn: "own definition", ucSame: "same rule", ucNo: "no data",
      ucSource: "UN DESA, World Urbanization Prospects 2025",
    },
    fr: {
      ucTitle: "Quelle est la part urbaine de chaque pays ?", ucPlay: "Lecture", ucPause: "Pause", ucYear: "Année", ucCount: "Compter",
      ucModes: { own: "définition propre à chaque pays", common: "même règle : villes et bourgs", cities: "même règle : villes seulement" },
      ucHead: { own: "Part urbaine, selon la définition de chaque pays", common: "Part vivant en ville ou dans un bourg, selon la même règle partout", cities: "Part vivant en ville, selon la même règle partout" },
      ucRule: "Même règle (degré d'urbanisation de l'ONU) : une ville compte au moins 50 000 habitants à 1 500 par km² ou plus ; un bourg au moins 5 000 à 300 par km² ou plus.",
      ucWorld: "Monde", ucCities: "villes", ucTowns: "bourgs", ucRural: "rural", ucUrban: "urbain",
      ucOwn: "définition propre", ucSame: "même règle", ucNo: "pas de données",
      ucSource: "ONU DESA, World Urbanization Prospects 2025",
    },
  });

  R_.sims["urban-count"] = function (container, opts = {}) {
    const GE = R_.geology, U = R_.urban, D = R_.data && R_.data.urban;
    const { L, tr, th, ctx, text, wrap, measure, panel } = GE.stage(container, opts, tr => `
      <label>${tr("ucCount")} <select class="uc-mode">${Object.entries(tr("ucModes")).map(([k, s]) => `<option value="${k}">${s}</option>`).join("")}</select></label>
      <button class="uc-play">${tr("ucPlay")}</button>
      <label>${tr("ucYear")} <input class="uc-year" type="range" step="5"></label>`);
    const W = GE.W, H = GE.H, MAP = { x: 10, y: 108, w: W - 20, h: 400 };
    if (!D || !R_.data.countries) { text("…", W / 2, H / 2, { align: "center" }); return; }
    const [Y0, Y1] = D.years, STEP = D.step;
    let year = Math.max(Y0, Math.min(Y1, Math.round((+opts.year || 2025) / STEP) * STEP));
    let mode = ["own", "common", "cities"].includes(opts.mode) ? opts.mode : "own", playing = false, t = 0, hover = null;
    const dark = th.name !== "light";
    const SEA = dark ? "#202226" : "#f4f6f8", EDGE = dark ? "rgba(20,22,26,0.9)" : "#ffffff", NODATA = dark ? "#33363b" : "#dcdcdc";
    const PART = dark ? ["#ff6a2b", "#e3b26b", "#6d8a5e"] : ["#d9561c", "#d6a14f", "#5f8a4f"];
    const { countries } = U.world(MAP);

    const idx = () => (year - Y0) / STEP;
    const value = (rec, m = mode) => {
      if (!rec) return null;
      const i = idx();
      if (m === "own") return rec.n[i];
      const d = rec.d[i];
      if (!d || d[0] == null) return null;
      return m === "cities" ? d[0] : d[0] + d[1];
    };

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.save(); ctx.beginPath(); ctx.rect(MAP.x, MAP.y, MAP.w, MAP.h); ctx.clip();
      ctx.fillStyle = SEA; ctx.fillRect(MAP.x, MAP.y, MAP.w, MAP.h);
      countries.forEach(k => { const v = value(D.countries[k.iso]); ctx.fillStyle = v == null ? NODATA : U.shade(th, v); ctx.fill(k.path, "evenodd"); });
      ctx.strokeStyle = EDGE; ctx.lineWidth = 0.6; countries.forEach(k => ctx.stroke(k.path));
      if (hover) { ctx.strokeStyle = th.text; ctx.lineWidth = 2.2; ctx.stroke(hover.k.path); }
      text(tr("ucSource"), MAP.x + MAP.w - 6, MAP.y + MAP.h - 8, { size: 11, align: "right", color: th.muted, halo: SEA });
      ctx.restore();

      // title, what is shown, the year
      text(tr("ucTitle"), MAP.x + 2, 30, { size: 24, weight: 700, color: th.accent });
      text(tr("ucHead")[mode], MAP.x + 2, 52, { size: 15, color: th.muted });
      text(String(year), W - 14, 46, { size: 40, weight: 700, align: "right" });

      // key, on the map's lower left
      const ky = MAP.y + MAP.h - 26, labels = ["< 20 %", "20–40", "40–60", "60–80", "≥ 80 %"];
      ctx.fillStyle = dark ? "rgba(20,22,26,0.82)" : "rgba(255,255,255,0.88)"; ctx.fillRect(MAP.x + 6, ky - 18, 420, 30);
      let kx = MAP.x + 14;
      labels.forEach((s, j) => { ctx.fillStyle = U.SHADES[dark ? "dark" : "light"][j]; ctx.fillRect(kx, ky - 10, 18, 13); text(s, kx + 24, ky + 2, { size: 14 }); kx += 34 + measure(s, 14); });

      // the world, above the map: own definition, then the three parts by the same rule
      const w = D.regions.world, i = idx(), by = 86;
      text(tr("ucWorld"), MAP.x + 2, by + 8, { size: 20, weight: 700 });
      text(`${tr("ucOwn")}: ${U.pct(L, w.n[i])} ${tr("ucUrban")}`, MAP.x + 90, by + 8, { size: 17, color: mode === "own" ? th.accent : th.text, weight: mode === "own" ? 700 : 400 });
      const bx = 520, bw = W - bx - 20, d = w.d[i];
      text(tr("ucSame"), bx - 12, by + 8, { size: 15, align: "right", color: mode === "own" ? th.muted : th.accent });
      let x = bx;
      [0, 1, 2].forEach(j => {
        const ww = bw * d[j] / 100;
        ctx.fillStyle = PART[j]; ctx.globalAlpha = mode === "cities" && j > 0 ? 0.45 : 1; ctx.fillRect(x, by - 10, ww, 24); ctx.globalAlpha = 1;
        const s = `${[tr("ucCities"), tr("ucTowns"), tr("ucRural")][j]} ${U.pct(L, d[j])}`;
        if (measure(s, 14, 700) < ww - 8) text(s, x + 6, by + 7, { size: 14, weight: 700, color: j === 2 && !dark ? "#ffffff" : "#1d1d1f" });
        x += ww;
      });
      // the rule, below the map on the right (the controls of a keynote are on the left)
      wrap(tr("ucRule"), 640, MAP.y + MAP.h + 26, W - 660, 18, { size: 13, color: th.muted });
      if (hover) drawHover();
    }

    function pick(sx, sy) {
      const k = countries.find(k => U.inside(k.rings, sx, sy));
      if (!k) return null;
      const rec = D.countries[k.iso], i = idx(), lines = [[U.nameOf(k.c, L), true]];
      if (!rec) lines.push([tr("ucNo")]);
      else {
        lines.push([`${tr("ucOwn")}: ${U.pct(L, rec.n[i])} ${tr("ucUrban")}`]);
        const d = rec.d[i];
        if (d && d[0] != null) lines.push([`${tr("ucSame")}: ${tr("ucCities")} ${U.pct(L, d[0])} · ${tr("ucTowns")} ${U.pct(L, d[1])} · ${tr("ucRural")} ${U.pct(L, d[2])}`]);
      }
      return { k, x: sx, y: sy, lines };
    }
    function drawHover() {
      const w = Math.max(...hover.lines.map(([s, b]) => measure(s, 14, b ? 700 : 400))) + 20, h = hover.lines.length * 19 + 10;
      let x = hover.x + 14, y = hover.y + 14;
      if (x + w > W - 4) x = hover.x - 14 - w;
      if (y + h > H - 4) y = hover.y - 14 - h;
      ctx.fillStyle = "rgba(20,22,26,0.94)"; ctx.fillRect(x, y, w, h);
      hover.lines.forEach(([s, b], j) => text(s, x + 10, y + 19 + j * 19, { size: 14, weight: b ? 700 : 400, color: "#ffffff" }));
    }

    const canvas = ctx.canvas, pos = e => { const r = canvas.getBoundingClientRect(); return [(e.clientX - r.left) * W / r.width, (e.clientY - r.top) * H / r.height]; };
    canvas.addEventListener("pointermove", e => { const [x, y] = pos(e); hover = y > MAP.y && y < MAP.y + MAP.h ? pick(x, y) : null; draw(); });
    canvas.addEventListener("pointerleave", () => { hover = null; draw(); });

    const sel = panel.querySelector(".uc-mode"), play = panel.querySelector(".uc-play"), slider = panel.querySelector(".uc-year");
    sel.value = mode; slider.min = Y0; slider.max = Y1; slider.value = year;
    const blur = el => { if (container.closest(".reveal")) setTimeout(() => el.blur(), 0); };
    function setYear(y) { year = Math.max(Y0, Math.min(Y1, y)); slider.value = year; if (hover) hover = pick(hover.x, hover.y); draw(); }
    function stop() { playing = false; play.textContent = tr("ucPlay"); }
    sel.addEventListener("change", () => { mode = sel.value; if (hover) hover = pick(hover.x, hover.y); draw(); blur(sel); });
    play.addEventListener("click", () => { if (playing) { stop(); return; } if (year >= Y1) year = Y0; playing = true; t = 0; play.textContent = tr("ucPause"); });
    slider.addEventListener("input", () => { stop(); setYear(+slider.value); });
    draw();
    GE.run(container, dt => { if (!playing) return; t += dt / 0.6; if (t >= 1) { t = 0; if (year >= Y1) stop(); else setYear(year + STEP); } });
    R_.page.onThemeChange(draw);
  };
})(globalThis);

// ---- src/sims/urban/world-cities.js ----
// Sim "world-cities": the cities of the world from 1975 to 2050 (UN DESA, World Urbanization Prospects 2025, cities by
// the Degree of Urbanisation: at least 50 000 people living at 1 500 per km² or more). Each city of 300 000 people or
// more (in 2025 or 2050) is a disc whose area grows with its population; megacities (10 million or more) in the
// accent colour. On the right, the ten largest cities of the year. Play: the years go by (between the 5-year values of
// the UN, the populations are interpolated); move over a city: its population.
//   <div class="geores" data-sim="world-cities" data-year="2025"></div>
//   data-region: boswash, tokaido, banana (the megalopolises), switzerland: a closer view, the ten largest of the region
// Data: dist/urban.js (tools/urban-data.R) and dist/countries.js.
(function (G) {
  const R_ = G.GeoRes;

  R_.addStrings({
    en: {
      wkTitle: "The cities of the world", wkPlay: "Play", wkPause: "Pause", wkYear: "Year",
      wkHint: "Every city of 300 000 people or more. Move over a city.", wkTop: "The ten largest",
      wkMega: n => `${n} megacities (10 million or more)`, wkKey: ["10 million or more", "5 to 10 million", "1 to 5 million", "less than 1 million"],
      wkM: "million", wkK: "thousand", wkProj: "projection",
      wkSource: "UN DESA, World Urbanization Prospects 2025 · cities by the Degree of Urbanisation",
      wkRegions: { boswash: "BosWash: from Boston to Washington", tokaido: "The Tōkaidō: from Tokyo to Osaka", banana: "The \"blue banana\": from London to Milan", switzerland: "Switzerland" },
    },
    fr: {
      wkTitle: "Les villes du monde", wkPlay: "Lecture", wkPause: "Pause", wkYear: "Année",
      wkHint: "Toutes les villes de 300 000 habitants ou plus. Passez sur une ville.", wkTop: "Les dix plus grandes",
      wkMega: n => `${n} mégapoles (10 millions ou plus)`, wkKey: ["10 millions ou plus", "5 à 10 millions", "1 à 5 millions", "moins d'un million"],
      wkM: "millions", wkK: "milliers", wkProj: "projection",
      wkSource: "ONU DESA, World Urbanization Prospects 2025 · villes selon le degré d'urbanisation",
      wkRegions: { boswash: "BosWash : de Boston à Washington", tokaido: "Le Tōkaidō : de Tokyo à Osaka", banana: "La « banane bleue » : de Londres à Milan", switzerland: "Suisse" },
    },
  });

  R_.sims["world-cities"] = function (container, opts = {}) {
    const GE = R_.geology, U = R_.urban, D = R_.data && R_.data.urban;
    const { L, tr, th, ctx, text, measure, panel } = GE.stage(container, opts, tr => `
      <button class="wc-play">${tr("wkPlay")}</button>
      <label>${tr("wkYear")} <input class="wc-year" type="range" step="1"></label>`);
    const W = GE.W, H = GE.H, MAP = { x: 6, y: 62, w: 930, h: 500 }, SIDE = { x: 950, y: 62, w: W - 962 };
    if (!D || !R_.data.countries) { text("…", W / 2, H / 2, { align: "center" }); return; }
    const [C0, C1] = D.cyears;
    let year = Math.max(C0, Math.min(C1, +opts.year || 2025)), playing = false, hover = null;
    const dark = th.name !== "light";
    const SEA = dark ? "#202226" : "#f4f6f8", LAND = dark ? "#3a3d43" : "#e6e2da", EDGE = dark ? "#2a2c2f" : "#ffffff";
    const COL = dark ? [th.accent, "#f2a65e", "#e8d3a8", "#9aa0a8"] : [th.accent, "#e07f30", "#c99a52", "#8a8f96"];
    const region = U.REGIONS[opts.region] ? opts.region : null;
    const { P, countries, inRegion } = U.world(MAP, region);
    const cities = D.cities.filter(c => inRegion(c[3], c[2])).map(([name, iso, lat, lon, cap, pop]) => ({ name, iso, cap, pop, xy: P(lon, lat) }));
    const cname = {};
    (R_.data.countries || []).forEach(c => { cname[U.iso(c)] = U.nameOf(c, L); });

    // population (thousands) in a year, interpolated between the 5-year values
    const popAt = (c, y) => {
      const f = (y - C0) / 5, i = Math.min(Math.floor(f), c.pop.length - 2), a = c.pop[i], b = c.pop[i + 1];
      return a + (b - a) * (f - i);
    };
    const R = p => Math.sqrt(Math.max(p, 0) / 1000) * (region ? 7 : 3.2);   // radius per √million (larger in a region)
    const cls = p => (p >= 10000 ? 0 : p >= 5000 ? 1 : p >= 1000 ? 2 : 3);
    const fmt = p => (p >= 1000 ? `${R_.num(L, p / 1000, p >= 10000 ? 1 : 2)} ${tr("wkM")}` : `${GE.big(L, Math.round(p))} ${tr("wkK")}`);

    function draw() {
      ctx.clearRect(0, 0, W, H);
      const now = cities.map(c => ({ c, p: popAt(c, year) })).filter(x => x.p > 0).sort((a, b) => b.p - a.p);
      // the map, the smallest cities on top
      ctx.save(); ctx.beginPath(); ctx.rect(MAP.x, MAP.y, MAP.w, MAP.h); ctx.clip();
      ctx.fillStyle = SEA; ctx.fillRect(MAP.x, MAP.y, MAP.w, MAP.h);
      ctx.fillStyle = LAND; countries.forEach(k => ctx.fill(k.path, "evenodd"));
      ctx.strokeStyle = EDGE; ctx.lineWidth = 0.5; countries.forEach(k => ctx.stroke(k.path));
      now.forEach(({ c, p }) => {
        const k = cls(p), r = Math.max(1.2, R(p));
        ctx.beginPath(); ctx.arc(c.xy[0], c.xy[1], r, 0, 2 * Math.PI);
        ctx.fillStyle = COL[k]; ctx.globalAlpha = k === 3 ? 0.75 : 0.62; ctx.fill(); ctx.globalAlpha = 1;
        if (k < 2) { ctx.strokeStyle = dark ? "rgba(255,255,255,0.7)" : "rgba(0,0,0,0.45)"; ctx.lineWidth = 0.8; ctx.stroke(); }
      });
      if (hover) { ctx.beginPath(); ctx.arc(hover.c.xy[0], hover.c.xy[1], Math.max(4, R(popAt(hover.c, year))) + 2, 0, 2 * Math.PI); ctx.strokeStyle = th.text; ctx.lineWidth = 2; ctx.stroke(); }
      text(tr("wkSource"), MAP.x + MAP.w - 6, MAP.y + MAP.h - 8, { size: 11, align: "right", color: th.muted, halo: SEA });
      // key
      const ky = MAP.y + MAP.h - 30;
      ctx.fillStyle = dark ? "rgba(20,22,26,0.82)" : "rgba(255,255,255,0.88)"; ctx.fillRect(MAP.x + 6, ky - 16, 600, 26);
      let kx = MAP.x + 18;
      tr("wkKey").forEach((s, j) => { ctx.beginPath(); ctx.arc(kx, ky - 3, 6, 0, 2 * Math.PI); ctx.fillStyle = COL[j]; ctx.fill(); text(s, kx + 11, ky + 2, { size: 13 }); kx += 30 + measure(s, 13); });
      ctx.restore();

      // title and year
      text(region ? tr("wkRegions")[region] : tr("wkTitle"), MAP.x + 4, 30, { size: 24, weight: 700, color: th.accent });
      text(tr("wkHint"), MAP.x + 4, 52, { size: 15, color: th.muted });
      text(String(Math.floor(year)), W - 14, 46, { size: 40, weight: 700, align: "right" });
      if (year > 2025) text(tr("wkProj"), W - 14, 60, { size: 13, align: "right", color: th.muted });

      // the ten largest, with bars
      const mega = now.filter(x => x.p >= 10000).length;
      text(tr("wkMega")(mega), SIDE.x, SIDE.y + 18, { size: 16, weight: 700, color: th.accent });
      text(tr("wkTop"), SIDE.x, SIDE.y + 50, { size: 15, color: th.muted });
      const top = now.slice(0, 10), max = Math.max(45000, top[0] ? top[0].p : 1);
      top.forEach(({ c, p }, j) => {
        const y = SIDE.y + 76 + j * 40;
        text(`${j + 1}. ${c.name}`, SIDE.x, y, { size: 15, weight: 700 });
        text(R_.num(L, p / 1000, 1), SIDE.x + SIDE.w, y, { size: 15, align: "right" });
        ctx.fillStyle = COL[cls(p)]; ctx.fillRect(SIDE.x, y + 6, SIDE.w * p / max, 9);
        text(cname[c.iso] || c.iso, SIDE.x + SIDE.w * p / max + 6, y + 15, { size: 11, color: th.muted });
      });
      text(`(${tr("wkM")})`, SIDE.x + SIDE.w, SIDE.y + 50, { size: 13, align: "right", color: th.muted });
      if (hover) drawHover();
    }

    function pick(sx, sy) {
      let best = null, bd = 1e9;
      cities.forEach(c => { const p = popAt(c, year); if (p <= 0) return; const d = Math.hypot(c.xy[0] - sx, c.xy[1] - sy) - Math.max(4, R(p)); if (d < bd) { bd = d; best = c; } });
      return best && bd < 4 ? { c: best, x: sx, y: sy } : null;
    }
    function drawHover() {
      const c = hover.c, lines = [[c.name, true], [cname[c.iso] || c.iso], [fmt(popAt(c, year))]];
      const w = Math.max(...lines.map(([s, b]) => measure(s, 14, b ? 700 : 400))) + 20, h = lines.length * 19 + 10;
      let x = hover.x + 14, y = hover.y + 14;
      if (x + w > W - 4) x = hover.x - 14 - w;
      if (y + h > H - 4) y = hover.y - 14 - h;
      ctx.fillStyle = "rgba(20,22,26,0.94)"; ctx.fillRect(x, y, w, h);
      lines.forEach(([s, b], j) => text(s, x + 10, y + 19 + j * 19, { size: 14, weight: b ? 700 : 400, color: "#ffffff" }));
    }

    const canvas = ctx.canvas, pos = e => { const r = canvas.getBoundingClientRect(); return [(e.clientX - r.left) * W / r.width, (e.clientY - r.top) * H / r.height]; };
    canvas.addEventListener("pointermove", e => { const [x, y] = pos(e); hover = x < MAP.x + MAP.w && y > MAP.y && y < MAP.y + MAP.h ? pick(x, y) : null; draw(); });
    canvas.addEventListener("pointerleave", () => { hover = null; draw(); });

    const play = panel.querySelector(".wc-play"), slider = panel.querySelector(".wc-year");
    slider.min = C0; slider.max = C1; slider.value = Math.round(year);
    function setYear(y) { year = Math.max(C0, Math.min(C1, y)); slider.value = Math.round(year); draw(); }
    function stop() { playing = false; play.textContent = tr("wkPlay"); }
    play.addEventListener("click", () => { if (playing) { stop(); return; } if (year >= C1) year = C0; playing = true; play.textContent = tr("wkPause"); });
    slider.addEventListener("input", () => { stop(); setYear(+slider.value); });
    draw();
    GE.run(container, dt => { if (!playing) return; const y = year + dt * 4; if (y >= C1) { setYear(C1); stop(); } else setYear(y); });
    R_.page.onThemeChange(draw);
  };
})(globalThis);

// Images next to this script, then mount every .geores element of the page
(function () {
  const script = document.currentScript;
  const base = script ? script.src.replace(/[^/]*$/, "") : "";
  GeoRes.images = Object.assign({"bluemarble":"bluemarble.jpg","blackmarble":"blackmarble.jpg","atmosphere":"atmosphere.jpg","helicopter":"helicopter.png","cloud":"cloud.png","watercycle":"watercycle.jpg","cloudtypes":"cloudtypes.jpg","nemap1880":"nemap1880.png","nemap1950":"nemap1950.png","nemaptoday":"nemaptoday.png","vrmap1960":"vrmap1960.png","vrmap1990":"vrmap1990.png","vrmaptoday":"vrmaptoday.png","bernmap":"bernmap.jpg","nemap17":"nemap17.jpg","nemap15":"nemap15.jpg","nemap13":"nemap13.jpg","nemap11":"nemap11.jpg","cdvmap":"cdvmap.jpg"}, GeoRes.images || {});
  Object.keys(GeoRes.images).forEach(k => {
    if (!/^(data:|https?:|\/)/.test(GeoRes.images[k])) GeoRes.images[k] = base + GeoRes.images[k];
  });
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", () => GeoRes.mount());
  else GeoRes.mount();
})();
